    bild: "assets/images/monster/almanach/annis-vettel.png",
    beschreibung: [
      "Annis-Vetteln hausen in Bergen oder Hügeln. Obwohl sie bucklig und missgestaltet sind, stellen sie mit ihrer Größe von 2,40 m die größten und körperlich eindrucksvollsten ihrer Art dar.",
      "Folterer der Schwachen. Auch wenn Annis-Vetteln mühelos einen erwachsenen Mann in Stücke reißen können, lieben sie es doch, Kinder zu jagen, weil sie ihr Fleisch mehr schätzen als alles andere. Sie nutzen die abgezogene Haut ihrer Opfer, um geschmeidiges Leder herzustellen. Annis-Vetteln hinterlassen Zeichen ihrer Grausamkeit an den Rändern von Wäldern und anderen Gebieten, die sie beanspruchen, und erzeugen so Furcht und Paranoia in nahen Dörfern.",
      "Verderber der Kinder. Wenn eine Annis in einer besonders grausamen Laune ist, verkleidet sie sich als freundlich aussehende ältere Dame, nähert sich einem Kind an einem abgelegenen Ort und schenkt ihm ein eisernes Zeichen, durch das es mit der Vettel über große Entfernung zu sprechen vermag. Im Laufe der Zeit überzeugt die 'Oma' das Kind, dass es in Ordnung ist, böse Gedanken zu haben und schlimme Dinge zu tun.",
      "Stammesmutter. So wie sich Annis-Vetteln Kindern nähern, um sich mit ihnen anzufreunden, haben sie auch die Tendenz, eine Gruppe von Ogern, Trollen oder anderen grobschlächtigeren Kreaturen zu adoptieren und sie mittels brutaler Stärke, Beschimpfungen und Aberglauben zu beherrschen."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für die Vettel ist Charisma (Zauberrettungswurf-SG 13). Sie kann angeboren die folgenden Zauber wirken: Jeweils 3/Tag: Selbstverkleidung (nimmt die Form eines mittelgroßen Humanoiden an), Nebelwolke." },
      { name: "Eisernes Zeichen", beschreibung: "Eine Annis-Vettel kann einen ihrer Eisenzähne oder Eisennägel herausziehen und 1 Minute damit verbringen, ihn zu polieren und zu einer Münze, einem Ring oder einem winzigen Spiegel zu formen. Danach ist jede Kreatur, die das eiserne Zeichen in der Hand hält, dazu in der Lage, ein geflüstertes Gespräch mit der Vettel zu führen, vorausgesetzt beide befinden sich auf derselben Existenzebene und sind nicht weiter als 15 km voneinander entfernt. Eine Annis kann bis zu drei eiserne Zeichen gleichzeitig aktiv haben. Als Aktion kann sie die Richtung und ungefähre Entfernung zu all ihren aktiven Zeichen bestimmen und jedes augenblicklich deaktivieren." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Annis führt drei Angriffe aus: einen mit ihrem Biss und zwei mit ihren Klauen." },
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 15 (3W6+5) Stichschaden." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 15 (3W6+5) Hiebschaden." },
      { name: "Zermalmende Umarmung", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 36 (9W6+5) Wuchtschaden, und das Ziel ist gepackt (SG 15 zum Entkommen), wenn seine Größenkategorie groß oder kleiner ist. Bis der Haltegriff endet, erleidet das Ziel 36 (9W6+5) Wuchtschaden zu Beginn eines jeden Zugs der Vettel. Die Vettel kann keine Angriffe ausführen, solange sie eine Kreatur gepackt hat." }
    ],
