    umgebung: ["Andere Ebenen", "Stadt", "Unterirdisch"],
    bild: "assets/images/monster/almanach/babau.png",
    beschreibung: [
      "Dämonen und Teufel ringen beständig um die Kontrolle über die Unteren Ebenen. In einer dieser Schlachten kämpften die Legionen der Erzteufelin Glasya gegen die brüllenden Horden des Dämonenfürsten Graz'zt. Es heißt, dass Glasya ihren Widersacher mit dem Schwert verwunden konnte und sich die ersten Babau dort erhoben, wo sein Blut zu Boden fiel. Ihr plötzliches Erscheinen half dabei, Glasya zu vertreiben und sicherte Graz'zts Platz als einen der einflussreichsten Dämonenfürsten des Abyss.",
      "Ein Babau besitzt die Gerissenheit eines Teufels und die Blutgier eines Dämons. Er hat ledrig schwarze Haut, die sich straff über seine hagere Gestalt spannt. Aus der Hinterseite seines langgezogenen Schädels ragt ein gekrümmtes Horn. Der gehässige Blick eines Babau vermag einer Kreatur die Kraft zu rauben."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Babau ist Weisheit (Zauberrettungswurf-SG 11). Der Babau kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Dunkelheit, Furcht, Magie bannen, Metall erhitzen, Schweben." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Babau führt zwei Nahkampfangriffe aus. Er kann außerdem vor oder nach diesen Angriffen seinen Schwächenden Blick einsetzen." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 8 (1W8+4) Hiebschaden." },
      { name: "Speer", beschreibung: "Nahkampf- oder Fernkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m oder Reichweite 6/18 m, ein Ziel. Treffer: 7 (1W6+4) Stichschaden, oder 8 (1W8+4) Stichschaden, wenn die Waffe mit beiden Händen geführt wird." },
      { name: "Schwächender Blick", beschreibung: "Der Babau wählt eine Kreatur aus, die er sehen kann und die sich innerhalb von 6 m befindet. Das Ziel muss einen Konstitutionsrettungswurf gegen SG 13 ablegen. Bei einem Misserfolg verursacht das Ziel für 1 Minute nur halben Schaden mit Waffen, die auf Stärke basieren. Das Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt bei einem Erfolg beenden." }
    ],
