    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 20, DEX: 12, CON: 20, INT: 11, WIS: 14, CHA: 8 },
    rettungswuerfe: {},
    fertigkeiten: { "Athletik": 8, "Heimlichkeit": 7 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Verängstigt"],
    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 12,
    sprachen: ["Versteht die Gemeinsprache und die Sprachen des Erschaffers, kann aber nicht sprechen"],
    umgebung: ["Andere Ebenen", "Ruinen", "Stadt"],
    bild: "assets/images/monster/almanach/banderhobb.png",
    beschreibung: [
      "Ein Banderhobb ist eine Verschmelzung von Schatten und Fleisch. Durch dunkle Magie nehmen beide Komponenten eine gewaltige und abscheuliche humanoide Gestalt an, die an eine zweibeinge Kröte erinnert. Derartig hervorgebracht, dient der Banderhobb seinem Erschaffer kurzzeitig als Schläger, Dieb und Entführer.",
      "Während seiner kurzen Existenz versucht ein Banderhobb, die Befehle seines Erschaffers auszuführen. Er erfüllt seine Mission und schert sich nicht um das Leid, das ihm dabei zugefügt wird oder er selbst verursacht. Sein einziger Wunsch ist es, zu dienen und erfolgreich zu sein. Oft erhält ein Banderhobb die Aufgabe, ein bestimmtes Ziel aufzuspüren. Dabei ist er besonders gefährlich, wenn ihm eine Haarsträhne, ein persönlicher Gegenstand oder ein anderes Objekt ausgehändigt wird, das in einer Verbindung mit dem Ziel steht. Hat er einen solchen Gegenstand zur Verfügung, kann er den Aufenthaltsort eines Ziels auf große Entfernung spüren.",
      "Ein Banderhobb erfüllt seine Pflichten, bis seine Existenz endet. Wenn er vergeht, für gewöhnlich mehrere Tage nach seiner Erschaffung, bleiben nur teerartiger Schleim und Schatten zurück. Legenden sprechen von einem dunklen Turm im Shadowfell, wo sich die Finsternis manchmal neu formt und die Banderhobbs hausen.",
      "Ist das Ritual abgeschlossen, verbinden sich Fleisch, Geist und Schatten zu einer Kreatur von der Größe eines Ogers. Dieses neu erschaffene Monstrum besitzt dünne Glieder, die über seine große Stärke hinwegtäuschen. Der breite Kiefer verbirgt eine lange Zunge und eine Reihe von Reißzähnen, mit der das Monster Kreaturen und Gegenstände, die es stehlen will, packt und verschluckt. Trotz seiner Größe macht ein Banderhobb kaum ein Geräusch und bewegt sich so leise wie die Schatten, aus denen er besteht. Die Kreatur kann nicht sprechen, aber Befehle ihres Erschaffers verstehen und mit anderen Banderhobbs auf psychische Weise kommunizieren.",
      "In den frühesten Tagen der Welt entwickelte ein Zirkel von Nachtvetteln ein Ritual, das zur Erschaffung des ersten Banderhobbs führte. Eine Vettel, die das Ritual kennt, könnte es jemandem für die richtige Bezahlung beibringen. Einige andere dunkle Feenwesen und mächtige Unholde besitzen dieses Wissen ebenfalls, genauso wie einige sterbliche Magier. Die entsprechenden Anweisungen könnten auch in Folianten über verdorbene Magie zu finden sein."
    ],
    besonderheiten: [
      { name: "Resonante Verbindung", beschreibung: "Wenn der Banderhobb ein winziges Stück einer Kreatur oder eines Gegenstands zur Verfügung hat, wie eine Haarsträhne oder einen Holzsplitter, kennt er den direktesten Weg zur Kreatur oder dem Objekt, wenn sich das Ziel innerhalb von 1,5 km befindet." },
      { name: "Schattenschleicher", beschreibung: "Solange sich der Banderhobb in dämmrigem Licht oder Dunkelheit befindet, kann er sich als Bonusaktion verstecken." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 22 (5W6+5) Stichschaden, und das Ziel ist gepackt (SG 15 zum Entkommen), wenn seine Größenkategorie groß oder kleiner ist. Bis der Haltegriff endet, ist die Kreatur festgesetzt und der Banderhobb kann seinen Biss- oder Zungen-Angriff nicht gegen ein anderes Ziel verwenden." },
      { name: "Zunge", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 4,5 m, eine Kreatur. Treffer: 10 (3W6) nekrotischer Schaden, und das Ziel muss einen Stärkerettungswurf gegen SG 15 ablegen. Bei einem Misserfolg wird das Ziel in einen Bereich innerhalb von 1,5 m um den Banderhobb gezogen, der dann eine Bonusaktion verwenden kann, um einen Biss-Angriff gegen das Ziel auszuführen." },
      { name: "Verschlucken", beschreibung: "Der Banderhobb macht einen Biss-Angriff gegen eine mittelgroße oder kleinere Kreatur, die er gepackt hat. Wenn der Angriff trifft, wird das Ziel verschluckt, und der Haltegriff endet. Die verschluckte Kreatur ist blind und festgesetzt, hat vollständige Deckung gegen Angriffe und andere Effekte von außerhalb des Banderhobbs und erleidet 10 (3W6) nekrotischen Schaden zu Beginn eines jeden Zugs des Banderhobbs. Eine Kreatur, die auf diese Weise auf 0 Trefferpunkte fällt, erleidet keinen weiteren nekrotischen Schaden und wird stabilisiert. Der Banderhobb kann nur eine Kreatur auf einmal verschlucken. Solange er nicht kampfunfähig ist, kann er die Kreatur jederzeit in einen Bereich innerhalb von 1,5 m hochwürgen (dazu ist keine Aktion notwendig). Das Ziel landet liegend. Wenn der Banderhobb stirbt, wird die verschluckte Kreatur gleichermaßen emporgewürgt." },
      { name: "Schattenschritt", beschreibung: "Der Banderhobb teleportiert sich magisch 9 m in einen nicht besetzten Bereich in dämmrigem Licht oder Dunkelheit, den er sehen kann. Vor oder nach dem Teleport kann er einen Biss- oder Zungen-Angriff ausführen." }
    ],
