      { name: "Verspotten (2/Tag)", beschreibung: "Der Barde kann als Bonusaktion in seinem Zug eine Kreatur bestimmen, die sich innerhalb von 9 m befindet und die ihn hören kann. Dem Ziel muss ein Charismarettungswurf gegen SG 12 gelingen, um nicht bis zum Beginn des nächsten Zugs des Barden bei allen Attributs-, Angriffs- und Rettungswürfen im Nachteil zu sein." }
