    bild: "assets/images/monster/almanach/barghest.png",
    beschreibung: [
      "Vor langer Zeit handelte Maglubiyet, Herrscher der goblinoiden Götter, mit dem General von Gehenna ein Abkommen zur Unterstützung aus. Der General schickte Yugoloths, die für die Sache des Mächtigen starben. Doch als die Zeit kam, seinen Teil des Vertrags einzuhalten, zog sich Maglubiyet zurück. Um sich zu rächen, erschuf der General von Gehenna die Barghests, welche die Seelen von Goblinoiden verschlingen und Maglubiyet so die Truppen für seine Armee im Jenseits entziehen.",
      "Verzehrender der Seelen. Ein Barghest kommt als Kind von Goblin-Eltern auf die Welt, wie deren normalen Nachkommen. Die Kreatur wird als Goblin geboren und entwickelt dann die Fähigkeit, ihre wahre Gestalt anzunehmen: die eines wolfähnlichen, monströsen Hundes.",
      "Von der Mission des Generals von Gehenna erfüllt, siebzehn goblinoide Seelen zu verzehren, jagen Barghests ihre Opfer, töten sie und verschlingen ihre Körper. Seelen, die auf diese Weise verzehrt werden, können sich nicht Maglubiyets Armee in Acheron anschließen. Warum siebzehn? Weil es siebzehn Eide waren, die Maglubiyet in seinem Vertrag mit dem General brach.",
      "Ein Barghest giert nach dem Tag, an dem er seine Mission abschließen, nach Gehenna zurückkehren und direkt in den Yugoloth-Legionen des Generals dienen kann, doch tötet er Goblinoide nicht wahllos. Indem er die Seelen von Anführern und anderen mächtigen Individuen verzehrt, nicht die einfacher Goblins, kann sich ein Barghest in Acheron einen höheren Status erkaufen. Barghests halten ihr wahres Wesen in der Regel geheim und bringen ein oder zwei Goblins zur Strecke, wenn sich die Gelegenheit ergibt, bis sie erwachsen und stark genug sind, größere Beute zu jagen. Entdecken Goblins, dass ein Barghest unter ihnen ist, reagieren sie mit kriecherischer Unterwürfigkeit, um der Kreatur zu beweisen, dass sie es nicht wert sind, verschlungen zu werden.",
      "Durch Feuer verbannt. Ein Barghest meidet Kontakt mit großen, offenen Feuern. Jedes Feuer, das größer als sein Körper ist, dient als Tor nach Gehenna und verbannt den Unhold auf diese Ebene, wo er wahrscheinlich für sein Versagen von einem Yugoloth erschlagen oder versklavt wird."
    ],
    besonderheiten: [
      { name: "Gestaltwandler", beschreibung: "Der Barghest kann seine Aktion verwenden, um sich in einen Goblin (Größenkategorie klein) oder zurück in seine wahre Gestalt zu verwandeln. Abgesehen von Größe und Bewegungsrate bleiben seine Spielwerte gleich. Jede Ausrüstung, die er trägt oder in der Hand hält, wird nicht verwandelt. Der Barghest nimmt seine wahre Gestalt an, wenn er stirbt." },
      { name: "Feuerverbannung", beschreibung: "Wenn der Barghest seinen Zug beginnt, während er von Flammen umgeben ist, die mindestens 3 m hoch oder breit sind, muss ihm ein Charismarettungswurf gegen SG 15 gelingen, um nicht sofort nach Gehenna verbannt zu werden. Spontane Entladungen von Feuer (wie der Odem eines roten Drachen oder der Zauber Feuerball) haben diesen Effekt nicht." },
      { name: "Scharfer Geruchssinn", beschreibung: "Der Barghest ist im Vorteil bei Würfen auf Weisheit (Wahrnehmung), die auf dem Geruchssinn basieren." },
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Barghest ist Charisma (Zauberrettungswurf-SG 12). Der Barghest kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Einfache Illusion, Schweben, Spurloses Gehen. Jeweils 1/Tag: Dimensionstür, Einflüsterung, Person bezaubern." },
      { name: "Seelen Verzehren", beschreibung: "Ein Barghest kann von der Leiche eines Humanoiden fressen, den er getötet hat und der nicht länger als 10 Minuten verstorben ist, wobei er Fleisch und Seele verzehrt. Dies dauert mindestens 1 Minute und vernichtet den Leichnam. Die Seele des Opfers bleibt 24 Stunden lang im Barghest gefangen, danach wird sie aufgezehrt. Wenn der Barghest stirbt, ehe die Seele aufgezehrt ist, wird sie freigesetzt. Solange die Seele eines Humanoiden im Barghest gefangen ist, hat jede Form der Wiederbelebung, die anwendbar ist, nur eine Erfolgschance von 50 %. Gelingt der Versuch, wird die Seele aus dem Barghest befreit. Ist sie aber erst einmal aufgezehrt, vermag keine sterbliche Magie den Humanoiden wieder zum Leben zu erwecken." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff (nur wahre Gestalt): +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 13 (2W8+4) Stichschaden." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 8 (1W8+4) Hiebschaden." }
    ],
