    ruestungstyp: null,
    tp: 76,
    tp_wuerfel: "9W8+36",
    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 16, DEX: 11, CON: 18, INT: 5, WIS: 7, CHA: 3 },
    rettungswuerfe: { WEI: 1 },
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: ["Gift"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Erschöpfung", "Vergiftet"],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 8,
    sprachen: ["Versteht Sprachen, die sie zu Lebzeiten kannte, kann aber nicht sprechen"],
    umgebung: ["Ruinen", "Stadt", "Unterirdisch"],
    bild: "assets/images/monster/almanach/brut_von_kyuss.png",
    beschreibung: [
      "Kyuss war ein Hohepriester des Orcus, der Leichen aus Nekropolen raubte und mit ihnen seine ersten Bruten erschuf. Selbst Jahrhunderte nach seinem Tod vollführen seine wahnsinnigen Jünger noch immer die schrecklichen Riten, die sein kranker Verstand ersonnen hat.",
      "Wurmplage. Aus der Entfernung oder in schlechtem Licht sieht eine Brut von Kyuss aus wie ein gewöhnlicher Zombie. Wenn sie deutlicher zu erkennen ist, bemerkt man Dutzende kleiner grüner Würmer, die in und aus dem Körper kriechen. Diese Würmer springen auf nahe Humanoide und graben sich in ihr Fleisch. Ein Wurm, der in einen humanoiden Körper eindringt, sucht sich einen Weg bis zum Gehirn. Dort angekommen, tötet die winzige Kreatur den Wirt und belebt die Leiche zu einer Brut von Kyuss, die weitere Würmer hervorbringt. Die Seele des Toten bleibt dabei in seinem Kadaver gefangen, was verhindert, dass die Person wiedererweckt oder wiederbelebt werden kann, bis ihre wandelnde Leiche zerstört wird. Das Grauen der Seele, die in ihrem untoten Körper gefangen ist, treibt die Brut von Kyuss in den Wahnsinn.",
      "Endlose Fäulnis. Bruten von Kyuss sind ein Ausdruck von Orcus' Wunsch, alles Leben in ein untotes Dasein zu transformieren. Sich selbst überlassen, wandert eine einzelne Brut von Kyuss ziellos umher. Stößt sie auf eine lebende Kreatur, greift sie diese an, um noch mehr ihrer unheiligen Art zu erschaffen. Gleichgültig ob sie verstreut oder geballt auftreten, vermehren sich Bruten exponentiell, wenn sie nicht aufgehalten werden."
    ],
    besonderheiten: [
      { name: "Regeneration", beschreibung: "Die Brut von Kyuss regeneriert 10 Trefferpunkte zu Beginn eines jeden ihrer Züge, solange sie mindestens 1 Trefferpunkt besitzt und sich nicht in Sonnenlicht oder fließendem Wasser befindet. Wenn die Brut Säure-, Feuer- oder gleißenden Schaden erleidet, hat diese Eigenschaft zu Beginn des nächsten Zugs keinen Effekt. Die Brut stirbt nur, wenn sie ihren Zug mit 0 Trefferpunkten beginnt und nicht regenerieren kann." },
      { name: "Würmer", beschreibung: "Wenn die Brut von Kyuss Ziel eines Effekts wird, der Krankheiten heilt oder Flüche bricht, sterben alle Würmer, die ihren Körper befallen haben, und sie verliert die Aktion Grabender Wurm." },
      { name: "Untote Natur", beschreibung: "Eine Brut von Kyuss braucht weder Luft noch Nahrung, Wasser oder Schlaf." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Brut von Kyuss führt zwei Angriffe mit ihren Klauen aus und verwendet Grabender Wurm." },
      { name: "Grabender Wurm", beschreibung: "Ein Wurm springt aus der Brut von Kyuss auf einen Humanoiden, den diese sehen kann und der sich innerhalb von 3 m befindet. Der Wurm verbeißt sich in der Haut des Ziels, wenn diesem kein Geschicklichkeitsrettungswurf gegen SG 11 gelingt. Der Wurm ist ein winziger Untoter mit RK 6, 1 Trefferpunkt, dem Wert 2 (-4) in allen Attributen und einer Bewegungsrate von 30 cm. Solange sich der Wurm auf der Haut des Ziels befindet, kann er normal getötet oder mit einer Aktion abgeworfen werden (die Brut kann diese Aktion verwenden, um einen abgeworfenen Wurm auf einen Humanoiden springen zu lassen, den sie sehen kann und der sich innerhalb von 3 m um den Wurm befindet). Ansonsten gräbt sich der Wurm am Ende des nächsten Zugs des Ziels unter dessen Haut, wobei er ihm 1 Punkt Stichschaden zufügt. Danach erleidet das Ziel am Ende eines jeden seiner Züge 7 (2W6) Punkte nekrotischen Schaden pro Wurm in seinem Körper (maximal 10W6). Ein von Würmern befallenes Ziel stirbt, wenn es auf 0 Trefferpunkte reduziert wird, und erhebt sich 10 Minuten später als Brut von Kyuss. Wird ein befallenes Opfer Ziel eines Effekts, der Krankheiten heilt oder Flüche bricht, sterben alle Würmer, die seinen Körper befallen haben." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 6 (1W6+3) Hiebschaden plus 7 (2W6) nekrotischer Schaden." }
    ],
