    attribute: { STR: 12, DEX: 16, CON: 12, INT: 11, WIS: 14, CHA: 10 },
    rettungswuerfe: {},
    fertigkeiten: { "Athletik": 5, "Heimlichkeit": 5, "Religion": 2 },
    schadensresistenzen: [],
