    fertigkeiten: { "Akrobatik": 5, "Heimlichkeit": 7, "Täuschen": 2, "Wahrnehmung": 5 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Blindsicht 9 m", "Dunkelsicht 36 m"],
    passiveWahrnehmung: 15,
    sprachen: ["Elfisch", "Sylvanisch"],
    umgebung: ["Unterirdisch", "Stadt"],
    bild: "assets/images/monster/almanach/duesterling.png",
    beschreibung: [
      "Uralte Legenden sprechen von einem Feenwesen, das einst die Sommerkönigin verriet. Sein wahrer Name wurde aus den Geschichtsbüchern gestrichen, doch die Erzählungen nennen ihn Dubh Catha, 'Dunkle Krähe'. So groß war der Zorn der Sommerkönigin, dass sie alle Mitglieder seines Hauses verfluchte. Andere Feenwesen bezeichnen die Nachkommen von Dubh Cathas Haus als die Dubh Sith oder 'Düsterlinge' in der Gemeinsprache. Düsterlinge siedeln meist in abgelegenen Kavernen und Kammern unter den Städten anderer Völker. Von diesen Enklaven aus üben sie ihre Kunst als Diebe und Attentäter aus.",
      "Das tödliche Licht. Der Fluch der Sommerkönigin lässt den Körper eines Düsterlings Licht aufsaugen, wodurch die Kreatur verdorrt, als würde sie schnell altern. Aus diesem Grund bedecken sie jeden Teil ihres Körpers, wenn sie Helligkeit ausgesetzt werden könnten. Das Licht, das ein Düsterling im Laufe seines Lebens absorbiert hat, brennt sich bei seinem Tod explosionsartig nach außen, was die Kreatur und viele ihrer Besitztümer einäschert.",
      "Liebe zur Kunst. Trotz ihres Fluchs haben Düsterlinge noch eine starke Vorliebe für die Schönheit der Kunst. Ein Düsterling könnte es riskieren, einen Blick auf den Sonnenaufgang zu erhaschen oder eine winzige Kerze zu entzünden, um die Farben eines Gemäldes oder Edelsteins zu betrachten.",
      "Ältesten-Transformation. Ein weiser und angesehener Düsterling kann sich für ein Ritual qualifizieren, durch das er zu einem Ältesten wird. Andere Älteste kennzeichnen den Anwärter mit leuchtenden Tätowierungen, um einen Teil des absorbierten Lichts aus dem Körper zu leiten. Ist das Ritual erfolgreich, nimmt der Düsterling eine hochgewachsene und schöne Gestalt an, wie die eines Elfen mit grauer Haut. Sollte das Ritual fehlschlagen, stirbt der Anwärter."
    ],
    besonderheiten: [
      { name: "Todesfunke", beschreibung: "Wenn der Düsterling stirbt, blitzt nicht-magisches Licht in einem Radius von 3 m auf, wobei sein Körper und alle Besitztümer, die nicht aus Metall bestehen oder magisch sind, zu Asche verbrennen. Alle Kreaturen in dem Bereich, die das helle Licht sehen können, müssen einen Konstitutionsrettungswurf gegen SG 10 ablegen, um nicht bis zum Ende ihres nächsten Zugs blind zu werden." },
      { name: "Empfindlichkeit gegenüber Licht", beschreibung: "Solange sich der Düsterling in hellem Licht befindet, ist er im Nachteil bei Angriffswürfen sowie Würfen auf Weisheit (Wahrnehmung), die sich aufs Sehen beziehen." }
    ],
    aktionen: [
      { name: "Dolch", beschreibung: "Nahkampf- oder Fernkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,5 m oder 6/18 m, ein Ziel. Treffer: 5 (1W4+3) Stichschaden. Ist der Düsterling bei seinem Angriffswurf im Vorteil, verursacht er zusätzlich 7 (2W6) Stichschaden." }
    ],
    bonusaktionen: [],
