    gesinnung: "Neutral böse",
    cr: 1,
    xp: 200,
    rk: 13,
    ruestungstyp: "Magierrüstung (10 ohne)",
    tp: 33,
    tp_wuerfel: "6W8+6",
    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 13, DEX: 11, CON: 12, INT: 9, WIS: 11, CHA: 14 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: ["Feuer"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 36 m (durchdringt magische Dunkelheit)"],
    passiveWahrnehmung: 10,
    sprachen: ["Drakonisch", "Ignal"],
    umgebung: ["Gebirge", "Höhle", "Unterirdisch"],
    bild: "assets/images/monster/almanach/feuermolch-hexenmeister_von_imix.png",
    beschreibung: [
      "In Regionen mit heißen Quellen, vulkanischer Aktivität oder ähnlich heißen und feuchten Bedingungen kann man die Feuermolche finden. Diese humanoiden Amphibien leben in einer militaristischen Theokratie, die das elementare Feuer in seiner schlimmsten Verkörperung verehrt.",
      "Streben nach Hitze. Feuermolche benötigen heißes Wasser, um zu leben und sich fortzupflanzen. Sie werden träge, sowohl geistig als auch körperlich, wenn sie eine Woche ohne feuchte Hitze verbracht haben. Langfristiger Mangel daran kann eine Feuermolch-Gemeinschaft zum Erliegen bringen, da die Kreaturen in Kältestarre verfallen und sich ihre Eier nicht mehr entwickeln.",
      "Feuermolche graben nach Hitzequellen in der Erde, wie kochendem Schlamm und heißen Quellen, die sie ideale Orte für ihre Siedlungen darstellen lassen. Durch Grabungen und Abbau schaffen sie Wohnraum und sichern sich einen großen Vorrat an Mineralien für andere Zwecke wie Verhüttung, Schmiedekunst und Alchemie. Jeder Hort umfasst ein Netzwerk aus Tunneln und Rohren, um heiße Flüssigkeiten in die ganze Siedlung zu leiten.",
      "Die Alchemie, die ihr Volk praktiziert, konzentriert sich auf Feuer. Eine ihrer liebsten Mixturen ist eine Paste aus Schwefel, Mineralsalzen und Öl. Viele Feuermolche haben es sich zur Gewohnheit gemacht, diese Mischung zu kauen, da sie eine angenehme innere Wärme herbeiführt und ihnen erlaubt, einen kleinen Feuerball zu speien. Die meisten ihres Volkes tragen einen Behälter mit der Paste bei sich.",
      "Religiös und militant. Gesellschaft und Kultur der Feuermolche basieren auf der Anbetung von Imix, dem Prinzen des Bösen Feuers. Diese Religiosität macht ihr Volk aggressiv, zornig und grausam. Hexenmeister des Imix lehren, dass Krieger, die diese Eigenschaften in der Schlacht unter Beweis stellen, vom Feuerprinzen berührt werden und in einen fast unaufhaltsamen Kampfrausch verfallen.",
      "Hexenmeister des Imix befehligen die Krieger, die ihren Wert beweisen sollen, indem sie auf Plünderungen ausziehen und Schätze und Gefangene erbeuten. Nachdem die Hexenmeister das beste Raubgut als Gabe für Imix an sich genommen haben, wird die übrige Beute nach Leistung aufgeteilt. Gefangene, die keinen offensichtlichen Nutzen haben, werden Imix geopfert und dann gegessen. Wer dazu imstande scheint, unter Tage zu arbeiten und andere Aufgaben zu verrichten, wird für eine Weile als Sklave im Hort gehalten, ehe ihn dasselbe Schicksal erwartet.",
      "Wenn Feuermolche in den Krieg ziehen, nicht nur auf einen gelegentlichen Überfall, machen sie keine Gefangenen. Ihr Ziel ist kein anderes als die vollständige Auslöschung ihrer Feinde – und die größte Feindschaft verspüren sie für andere ihrer Art. Begegnen sich zwei Gruppen von Feuermolchen, ist es wahrscheinlich, dass sie um das gleiche Territorium wetteifern, und für gewöhnlich ist ein blutiger Kampf die Folge."
    ],
    besonderheiten: [
      { name: "Amphibisch", beschreibung: "Der Feuermolch kann Luft und Wasser atmen." },
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Feuermolch ist Charisma. Er kann beliebig oft Magierrüstung (nur Reichweite 'selbst') wirken, wobei keine Materialkomponenten nötig sind." },
      { name: "Zauberwirken", beschreibung: "Der Feuermolch ist ein Zauberwirker der 3. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 12, +4 zum Treffen mit Zauberangriffen). Er erhält seine verbrauchten Zauberplätze zurück, wenn er eine kurze oder lange Rast abschließt. Er kennt die folgenden Hexenmeisterzauber: Zaubertricks (beliebig oft): Feuerpfeil, Göttliche Führung, Licht, Magierhand, Taschenspielerei. 1.-2. Grad (2 Zauberplätze des 2. Grades): Brennende Hände, Flammenkugel, Höllischer Tadel, Sengender Strahl." },
      { name: "Segen des Imix", beschreibung: "Wenn der Feuermolch einen Gegner auf 0 Trefferpunkte reduziert, erhält er 5 temporäre Trefferpunkte." }
    ],
    aktionen: [
      { name: "Morgenstern", beschreibung: "Nahkampf-Waffenangriff: +3 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 5 (1W8+1) Stichschaden." }
    ],
