    bild: "assets/images/monster/almanach/flind.png",
    beschreibung: [
      "Ein Flind ist ein außerordentlich starker und brutaler Gnoll, der die Kriegsmeute befehligt, zu der er gehört. Er führt einen Flegel, den Yeenoghu mit mächtiger Magie erfüllt hat.",
      "In einer Kriegsmeute kann es nicht mehr als einen Flind geben, und dieser bestimmt den Pfad der ganzen Gruppe. Aufgrund seiner besonderen Verbindung mit Yeenoghu ist ein Flind in der Lage, die Gnolle durch Omen und dämonische Einsichten zu schwacher Beute zu führen, die abgeschlachtet werden soll.",
      "Im Gegensatz zu vielen humanoiden Anführern, die sich hinter ihren Schergen verschanzen, führt ein Flind den Angriff an der Spitze an. Sein Flegel verursacht bei einem Treffer quälende Schmerzen, Lähmung und Desorientierung."
    ],
    besonderheiten: [
      { name: "Aura des Blutdursts", beschreibung: "Solange der Flind nicht kampfunfähig ist, können alle Kreaturen mit der Eigenschaft Wüten als Bonusaktion einen Biss-Angriff ausführen, wenn sie sich innerhalb von 3 m um den Flind befinden." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Flind führt drei Angriffe aus: jeweils einen seiner Flegelangriffe oder drei mit seinem Langbogen." },
      { name: "Flegel des Wahnsinns", beschreibung: "Nahkampf-Waffenangriff: +9 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 10 (1W10+5) Wuchtschaden, und das Ziel muss einen Weisheitsrettungswurf gegen SG 16 ablegen. Bei einem Misserfolg muss es in seinem nächsten Zug einen Nahkampfangriff gegen ein zufälliges Ziel in Reichweite ausführen. Sind keine Ziele in Reichweite (selbst dann nicht, nachdem es sich bewegt hat), verliert es seine Aktion in diesem Zug." },
      { name: "Flegel der Schmerzen", beschreibung: "Nahkampf-Waffenangriff: +9 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 10 (1W10+5) Wuchtschaden plus 22 (4W10) psychischer Schaden." },
      { name: "Flegel der Lähmung", beschreibung: "Nahkampf-Waffenangriff: +9 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 10 (1W10+5) Wuchtschaden, und das Ziel muss einen erfolgreichen Konstitutionsrettungswurf gegen SG 16 ablegen, um nicht bis zum Ende seines nächsten Zugs gelähmt zu sein." },
      { name: "Langbogen", beschreibung: "Fernkampf-Waffenangriff: +4 zum Treffen, Reichweite 45/180 m, ein Ziel. Treffer: 4 (1W8) Stichschaden." }
    ],
