    bewegung: { "Gehen": "36 m" },
    attribute: { STR: 4, DEX: 23, CON: 13, INT: 10, WIS: 12, CHA: 7 },
    rettungswuerfe: {},
    fertigkeiten: { "Akrobatik": 8, "Fingerfertigkeit": 8, "Heimlichkeit": 8, "Wahrnehmung": 5 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 15,
    sprachen: ["Gemeinsprache", "Sylvanisch"],
    umgebung: ["Feenwildnis", "Wald"],
    bild: "assets/images/monster/almanach/flinkling.png",
    beschreibung: [
      "Flinklinge sausen durch die schaurigen, knorrigen Wälder, in denen die Feen des Winterhofs regieren, sowohl im Feywild als auch in der Welt der Sterblichen. Sie rennen so schnell, dass die Augen sie nicht erfassen können, und scheinen wenig mehr zu sein als ein verschwommenes Flimmern in der Luft.",
      "Ein Flinkling ist ein kleines, schlankes Feenwesen und ähnelt einem schmächtigen Elfen mit scharfen, wilden Gesichtszügen. Seine kalten, grausamen Augen leuchten wie Juwelen.",
      "Lebe schnell, stirb jung. Flinklinge verdanken ihre Existenz – und ihr Unglück – der Königin von Luft und Dunkelheit, der schrecklichen Herrscherin des Hofes der Abenddämmerung. Die Kreaturen, die zu den Flinklingen wurden, waren einst ein Volk von faulen, egoistischen Feenwesen und folgten dem Ruf ihrer Königin einmal zu oft zu spät. Um ihre Schritte zu beschleunigen und sie zu lehren, dem Willen ihrer Herrscherin zu folgen, ließ diese sie schrumpfen und vervielfachte ihr Lebenstempo. Der Fluch der Königin verlieh den Flinklingen ihre unglaubliche Geschwindigkeit, zwang ihnen aber auch die ruhelose Hast auf, mit der sie durch das Leben eilen – kein Flinkling wird älter als fünfzehn Jahre.",
      "Zu schnell für Worte. Aus der Perspektive eines Flinklings ist die Welt der Sterblichen ein schwerfälliger Ort: Wirbelstürme kriechen gemächlich über die Erde, Regen sinkt zu Boden wie langsame Schneeflocken, Blitze bewegen sich schleppend von Wolke zu Wolke. Die träge und langweilige Welt scheint von schläfrigen Kreaturen bewohnt zu sein, deren tiefe, blökende Sprache keine Bedeutung hat.",
      "Für andere Lebewesen ist ein Flinkling kaum wahrnehmbar schnell und ist nur als unbestimmter verschwommener Fleck zu erkennen, wenn er sich bewegt. Sein grausames Lachen klingt wie eine Salve schneller Staccatolaute, seine Sprache wie ein schrilles Quieken. Nur wenn ein Flinkling sich absichtlich verlangsamt, was er nicht gern tut, können andere Wesen ihn richtig sehen, hören und verstehen. Ein 'stehender' Flinkling ist niemals wirklich ruhig und bewegt sich ständig auf dem Fleck, als könnte er es kaum erwarten, wieder loszusausen.",
      "Chaos, nicht Mord. Flinklinge besitzen ein launenhaftes Wesen, das gut zu ihrer überbordenden Energie passt. Sie denken so schnell, wie sie rennen, und haben immer etwas vor. Ein Flinkling verbringt den Großteil seiner Zeit damit, langsameren Kreaturen Streiche zu spielen. Sie lassen kaum eine Gelegenheit verstreichen, einer Person die Schnürsenkel zusammenzubinden, einen Schemel wegzuziehen, auf den sie sich gerade setzen will, oder einen Sattel zu lösen, wenn niemand hinschaut.",
      "Solche Streiche sind jedoch mitnichten die Grenze ihrer bösartigen Schadenfreude. Zwar würden sie nie direkt einen Mord begehen, aber Flinklinge können ein Leben auf viele Arten ruinieren: Sie stehlen einen wichtigen Brief, klauen Münzen, die für die Armen gedacht waren, oder platzieren einen gestohlenen Gegenstand in jemandes Tasche. Flinklinge genießen es, Leid zu verursachen, das über bloße Streiche hinausgeht, besonders wenn die Schuld für ihre Taten anderen zugeschrieben wird und sie so für Zwietracht sorgen."
    ],
    besonderheiten: [
      { name: "Verschwommene Bewegung", beschreibung: "Angriffswürfe gegen den Flinkling sind im Nachteil, solange dieser nicht kampfunfähig oder festgesetzt ist." },
      { name: "Entrinnen", beschreibung: "Wenn der Flinkling einem Effekt ausgesetzt ist, der ihm einen Geschicklichkeitsrettungswurf erlaubt, um den Schaden zu halbieren, erleidet er bei einem erfolgreichen Rettungswurf gar keinen Schaden oder die Hälfte, wenn der Wurf misslingt." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Flinkling führt drei Angriffe mit seinem Dolch aus." },
      { name: "Dolch", beschreibung: "Nahkampf- oder Fernkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m oder 6/18 m, ein Ziel. Treffer: 8 (1W4+6) Stichschaden." }
    ],
    bonusaktionen: [],
