    attribute: { STR: 11, DEX: 16, CON: 16, INT: 20, WIS: 14, CHA: 16 },
    rettungswuerfe: { KON: 10, INT: 12, WEI: 9 },
    fertigkeiten: { "Arkane Kunde": 18, "Geschichte": 12, "Motiv erkennen": 9, "Wahrnehmung": 9 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Gift", "Wucht-, Stich- und Hiebschaden durch nicht-magische Angriffe"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Erschöpfung", "Bezaubert", "Gelähmt", "Verängstigt", "Vergiftet"],
    sinne: ["Wahre Sicht 36 m"],
    passiveWahrnehmung: 19,
    sprachen: ["Tiefensprache", "Gemeinsprache der Unterreiche", "Telepathie 36 m"],
    umgebung: ["Unterirdisch", "Andere Ebenen"],
    bild: "assets/images/monster/almanach/gedankenschinder-lich.png",
    beschreibung: [
      "Den Pfad zum wahren Lich können nur die mächtigsten Magier der Gedankenschinder beschreiten, da er die Fähigkeit erfordert, ein Seelengefäß zu erschaffen und den Zauber Einkerkerung zu wirken. Ein Gedankenschinder-Lich nutzt die Spielwerte des Lichs mit den folgenden Anpassungen: Er hat einen Herausforderungsgrad von 22, spricht Tiefensprache sowie die Gemeinsprache der Unterreiche und beherrscht Telepathie mit einer Reichweite von 36 m. Er besitzt die Merkmale Magieresistenz und Angeborenes Zauberwirken (Psionik) sowie die zusätzlichen Aktionen Tentakel, Gehirn entnehmen und Gedankenschlag. Solange der Gedankenschinder-Lich sein Seelengefäß mit gefangenen Seelen speist, behält er die Fähigkeiten, seine Tentakel einzusetzen und Gehirne zu entnehmen."
    ],
    besonderheiten: [
      { name: "Magieresistenz", beschreibung: "Der Lich ist im Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." },
      { name: "Angeborenes Zauberwirken (Psionik)", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Lich ist Intelligenz (Zauberrettungswurf-SG 20). Er kann angeboren die folgenden Zauber wirken, wobei keine Komponenten nötig sind: Beliebig oft: Gedanken wahrnehmen, Schweben. Jeweils 1/Tag: Monster beherrschen, Ebenenwechsel (nur Reichweite 'selbst')." },
      { name: "Zauberwirken", beschreibung: "Der Gedankenschinder-Lich ist ein Zauberwirker der 18. Stufe. Sein Attribut zum Zauberwirken ist Intelligenz (Zauberrettungswurf-SG 20, +12 zum Treffen mit Zauberangriffen). Er hat die Magierzauber eines gewöhnlichen Lichs vorbereitet (siehe Monsterbuch)." }
    ],
    aktionen: [
      { name: "Tentakel", beschreibung: "Nahkampf-Waffenangriff: +12 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 21 (3W10+5) psychischer Schaden. Wenn das Ziel eine Kreatur der Größenkategorie Groß oder kleiner ist, ist es gepackt (SG 15 zum Entkommen) und muss einen erfolgreichen Intelligenzrettungswurf gegen SG 20 ablegen, um nicht betäubt zu werden, bis der Haltegriff endet." },
      { name: "Gehirn entnehmen", beschreibung: "Nahkampf-Waffenangriff: +12 zum Treffen, Reichweite 1,5 m, ein kampfunfähiger Humanoider, der vom Gedankenschinder gepackt ist. Treffer: 55 (10W10) Stichschaden. Wenn dieser Schaden das Ziel auf 0 Trefferpunkte reduziert, tötet der Gedankenschinder es, indem er sein Gehirn entfernt und verzehrt." },
      { name: "Gedankenschlag (Aufladung 5-6)", beschreibung: "Der Lich gibt auf magische Weise psychische Energie in einem Kegel von 18 m ab. Jeder Kreatur in dem Bereich muss ein Intelligenzrettungswurf gegen SG 18 gelingen, um nicht 27 (5W8+5) Punkte psychischen Schaden zu erleiden und für 1 Minute betäubt zu werden. Die Kreatur kann diesen Rettungswurf am Ende eines jeden ihrer Züge wiederholen und den Effekt auf ihr bei einem Erfolg beenden." }
    ],
