    tp_wuerfel: "7W10+21",
    bewegung: { "Gehen": "12 m", "Klettern": "12 m" },
    attribute: { STR: 18, DEX: 16, CON: 16, INT: 5, WIS: 12, CHA: 7 },
    rettungswuerfe: {},
    fertigkeiten: { "Heimlichkeit": 5, "Wahrnehmung": 3 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 13,
    sprachen: [],
    umgebung: ["Dschungel", "Wald", "Ruinen"],
    bild: "assets/images/monster/almanach/girallon.png",
    beschreibung: [
      "Ein Girallon sieht aus wie ein übergroßer, vierarmiger Menschenaffe mit grauer Haut und weißem Pelz. Seine Reißzähne und Krallen unterscheiden ihn von gewöhnlichen Affen und zeigen deutlich, dass es sich um ein monströses Raubtier handelt.",
      "Girallons sind am weitesten in gemäßigten oder warmen Waldregionen verbreitet, in denen es viel Leben gibt. Sie teilen die Begabung des Affen zum Klettern, auch wenn die Kreaturen eine halbe Tonne wiegen und keine Bäume erklimmen, die ihr Gewicht nicht zu tragen vermögen. Die meiste Zeit pirschen sie auf dem Waldboden umher, lauern in engen Schluchten oder flachen Höhlen oder warten versteckt in Ruinen auf Beute. Ein Girallon geht mit überraschender Heimlichkeit vor, wenn man seine Größe und seinen Mangel an Tarnung bedenkt.",
      "Girallons bilden lose Gruppen aus mehreren Individuen samt deren Nachkommen, in der Regel angeführt von einem dominanten Erwachsenen, der oft das älteste Mitglied der Gruppe ist. Wenn sie abseits ihrer Behausung auf der Jagd sind, nutzen sie Brüllen und Körpersprache, um miteinander auf Entfernung zu kommunizieren. Jedes Individuum jagt normalerweise allein und weit von den anderen entfernt, damit alle angemessen viel Futter erhalten. Der Anführer könnte die Gruppe dazu bringen, gemeinsam wirklich große Beute zu erlegen. Wenn sie erfolgreich sind, teilen alle Mitglieder die Beute untereinander, wobei die besten Stücke an die Mütter gegeben werden, die sich um Junge kümmern.",
      "Die Ruinen von humanoiden Behausungen, besonders in tiefen Wäldern und Dschungeln, scheinen Girallons anzulocken. Sie bewegen sich mühelos auf Treppen, Balkonen, geneigten Dächern und Zinnen solcher Bauten. Für einen Girallon sind die Gebäude einer Stadt nur eine andere Art von Wald – und besser noch: ein Wald, dessen höchste „Äste“ die Kreatur mühelos tragen können. In einer solchen Umgebung nutzen die monströsen Tiere ihre Begabung zu klettern voll aus. Mit Leichtigkeit erklimmen sie Wände und Zinnen und hocken sich auf Turmspitzen und andere hohe Stellen, um die Umgebung im Auge zu behalten.",
      "Die sozialen Angewohnheiten wilder Girallons sind ungewöhnlich für Menschenaffen, genauso wie ihre instinktive Faszination für humanoide Bauwerke. Diese Umstände, zusammen mit dem Aussehen der Kreatur, haben Gelehrte zu der Meinung veranlasst, dass Girallons durch Magie erschaffen wurden, um als Wächter für ein längst verlorenes Imperium zu dienen. Nach dem Niedergang dieses Reiches verwilderten die Girallons und breiteten sich in der ganzen Welt aus.",
      "Seitdem haben viele Kreaturen versucht, die Monster zu zähmen, zu unterjochen oder mit ihnen einträglich auszukommen. Beispielsweise versklaven die Yuan-ti Girallons und verwenden sie als Grenzwächter für ihre Schlangenkönigreich. Weil die monströsen Wesen dafür bekannt sind, unter Artgenossen friedlich zu sein, haben einige Humanoide gelernt, den Anführer einer Gruppe mit Nahrung und anderen Geschenken für sich zu gewinnen, um eine Art Bündnis mit den Kreaturen zu schließen.",
      "Girallons, die gut behandelt werden, sind vielleicht bereit, als Wächter zu dienen, doch fehlt ihnen die Intelligenz, um kompliziertere Aufgaben anzunehmen, als Fremde anzugreifen, die ihr Revier betreten. Wenn sie jung gefangen und richtig ausgebildet werden, können Girallons an höchst unwahrscheinlichen Orten enden, etwa als Bewacher des Eingangs zur Diebesgilde einer Stadt. Wer einen Girallon als Haustier halten will, muss immer vorsichtig sein, denn die raubtierhaften Instinkte der Kreatur können jederzeit die Oberhand gewinnen."
    ],
    besonderheiten: [
      { name: "Aggressiv", beschreibung: "Als Bonusaktion kann sich der Girallon eine Distanz entsprechend seiner Bewegungsrate in Richtung einer feindlichen Kreatur bewegen, die er sehen kann." },
      { name: "Scharfer Geruchssinn", beschreibung: "Der Girallon ist im Vorteil bei Würfen auf Weisheit (Wahrnehmung), die auf dem Geruchssinn basieren." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Girallon führt fünf Angriffe aus: einen mit seinem Biss und vier mit seinen Klauen." },
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 7 (1W6+4) Stichschaden." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 7 (1W6+4) Hiebschaden." }
    ],
    bonusaktionen: [],
