    beschreibung: [
      "Manchmal wenden sich Gnolle gegeneinander, vielleicht um zu bestimmen, wer eine Kriegsmeute anführen soll, oder aus extremem Hunger. Selbst unter normalen Umständen können Gnolle, die zu lange keine Opfer in die Klauen bekommen, ihren Hunger und ihre gewalttätigen Triebe kaum kontrollieren. Am Ende kämpfen sie gegeneinander.",
      "Die Überlebenden verschlingen das Fleisch ihrer erschlagenen Kameraden, aber bewahren die Knochen auf. Dann erwecken sie die Überreste zu einem Anschein von Leben in der Gestalt eines Gnoll-Dörrlings, indem sie rituell Yeenoghu anrufen.",
      "Dörrlinge benehmen sich fast genauso wie lebende Gnolle. Sie reisen mit ihren Kameraden und versuchen, alles auf ihrem Weg zu töten. Allerdings fressen sie nicht und sind nicht von Yeenoghus Hunger angetrieben, sodass mehr Fleisch für die Kriegsmeute bleibt. Gnoll-Dörrlinge können keine Waffen führen, die über einen einfachen Knüppel hinausgehen.",
      "Untote Natur. Ein Gnoll-Dörrling braucht weder Luft noch Nahrung, Wasser oder Schlaf."
    ],
