    passiveWahrnehmung: 12,
    sprachen: ["Grungisch"],
    umgebung: ["Dschungel", "Wald"],
    bild: "assets/images/monster/almanach/grung.png",
    beschreibung: [
      "Grungs sind kleine aggressive, froschartige Humanoide, die man in Regenwäldern und tropischen Dschungeln findet. Sie sind extrem territorial und sehen sich als den meisten anderen Kreaturen überlegen.",
      "Grungs leben in Bäumen und bevorzugen Schatten. Ihre Brutplätze befinden sich am Boden in gut bewachten Tümpeln. Ungefähr drei Monate nach dem Schlüpfen ist eine Grung-Kaulquappe körperlich ausgewachsen. Als Erwachsener gilt der Jugendliche nach weiterer sechs bis neun Monaten.",
      "Die Gesellschaft der kleinen Humanoiden ist durch ein Kastensystem bestimmt. Jede Kaste legt Eier in einen eigenen Laichtümpel, und Heranwachsende schließen sich ihr an, sobald sie in der Lage sind, das Gelege selbstständig zu verlassen. Alle Grungs weisen bei der Geburt eine stumpfe grüngraue Farbe auf, nehmen aber den Farbton ihrer Kaste an, wenn sie erwachsen werden. Grüne Grungs sind die Krieger, Jäger und Arbeiter des Stammes, blaue arbeiten als Handwerker und in häuslichen Rollen. Beide Gruppen werden von den violetten Grungs überwacht und angeleitet, die als Verwalter und Anführer auftreten. Rote Grungs sind Gelehrte und Zauberwirker. Die orangefarbenen Grungs sind Elitekrieger über allen niederen Gruppen, und die goldenen Grungs nehmen die höchsten Führungspositionen ein.",
      "Für gewöhnlich bleibt ein Grung sein ganzes Leben in einer Kaste. In seltenen Fällen kann sich ein Individuum, das sich durch große Taten ausgezeichnet hat, die Einladung in eine höhere Kaste verdienen. Durch eine Kombination aus Kräutertinkturen und ritueller Magie ändert ein derart beförderter Grung die Farbe und wird in seine neue Kaste aufgenommen wie ein junges Mitglied. Ab diesem Zeitpunkt sind er und seine Nachkommen Mitglieder der höheren Kaste.",
      "Alle Grungs scheiden eine Substanz aus, die für sie selbst harmlos, aber für andere Kreaturen giftig ist. Sie nutzen dieses Gift auch, um ihre Waffen damit zu überziehen. Je nach Hautfarbe des Grungs kann das Gift einen zusätzlichen Effekt auslösen: Grünes Gift hindert das Opfer am normalen Bewegen, blaues zwingt es zu lautem Lärm, violettes weckt einen zwanghaften Drang, sich zu suhlen, rotes zwingt es zum Essen, oranges macht es vor Verbündeten verängstigt, und goldenes bezaubert es.",
      "Grungs suchen immer nach Kreaturen, die sie gefangen nehmen und versklaven können. Zwar setzen sie Sklaven auch für allerlei niedere Tätigkeiten ein, aber vor allem mögen sie es, sie zu schikanieren. Die armen Kreaturen werden mit leicht giftiger Nahrung gefüttert, um sie lethargisch und gefügig zu machen. Eine Person, die über längere Zeit unter dieser Behandlung leidet, wird eine leere Hülle ihres früheren Selbst und kann nur mit Magie zurückgebracht werden.",
      "Ein Grung, der nicht mindestens 1 Stunde am Tag im Wasser verbringt, erleidet eine Stufe Erschöpfung am Ende des Tages. Von dieser Erschöpfung kann er sich nur durch Magie erholen oder indem er sich für mindestens 1 Stunde im Wasser aufhält."
    ],
    besonderheiten: [
      { name: "Amphibisch", beschreibung: "Der Grung kann Luft und Wasser atmen." },
      { name: "Giftige Haut", beschreibung: "Jede Kreatur, die den Grung packt oder anderweitig in direkten Kontakt mit seiner Haut kommt, muss einen erfolgreichen Konstitutionsrettungswurf gegen SG 12 ablegen, um nicht für 1 Minute vergiftet zu werden. Eine Kreatur, die nicht mehr im direkten Kontakt mit dem Grung ist, kann den Rettungswurf am Ende eines jeden ihrer Züge wiederholen und den Effekt bei einem Erfolg beenden." },
      { name: "Stehender Sprung", beschreibung: "Der Grung springt 7,5 m weit und 4,5 m hoch, mit oder ohne Anlauf." }
    ],
    aktionen: [
      { name: "Dolch", beschreibung: "Nahkampf- oder Fernkampf-Waffenangriff: +4 zum Treffen, Reichweite 1,5 m oder Reichweite 6/18 m, ein Ziel. Treffer: 4 (1W4+2) Stichschaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 12 gelingen, um nicht 5 (2W4) Punkte Giftschaden zu erleiden." }
    ],
