      { name: "Zauberwirken", beschreibung: "Der Hervorrufer ist ein Zauberwirker der 12. Stufe. Sein Attribut zum Zauberwirken ist Intelligenz (Zauberrettungswurf-SG 15, +7 zum Treffen mit Zauberangriffen). Er hat die folgenden Magierzauber vorbereitet: Zaubertricks (beliebig oft): Feuerpfeil, Kältestrahl, Licht, Taschenspielerei. 1. Grad (4 Zauberplätze): Brennende Hände*, Magierrüstung, Magisches Geschoss*. 2. Grad (3 Zauberplätze): Nebelschritt, Spiegelbilder, Zerbersten*. 3. Grad (3 Zauberplätze): Blitz*, Feuerball*, Gegenzauber. 4. Grad (3 Zauberplätze): Eissturm*, Steinhaut. 5. Grad (2 Zauberplätze): Bigbys Hand*, Kältekegel*. 6. Grad (1 Zauberplatz): Eiswand*, Kugelblitz*. *Hervorrufungszauber des 1. Grades oder höher." },
      { name: "Zauberformen", beschreibung: "Wenn der Hervorrufer einen Hervorrufungszauber wirkt, der andere Kreaturen, die er sieht, zu einem Rettungswurf zwingt, kann er eine Anzahl von Kreaturen in Höhe des Zaubergrads+1 auswählen. Diesen Zielen gelingt der Rettungswurf automatisch. Wenn ein erfolgreicher Rettungswurf bedeutet, dass die Kreatur halben Schaden durch den Zauber erleidet, erleidet sie stattdessen gar keinen." }
