    attribute: { STR: 13, DEX: 12, CON: 14, INT: 16, WIS: 13, CHA: 11 },
    rettungswuerfe: {},
    fertigkeiten: { "Arkane Kunde": 5 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 11,
    sprachen: ["Gemeinsprache", "Goblinisch"],
    umgebung: ["Grasland", "Hügel", "Wald"],
    bild: "assets/images/monster/almanach/hobgoblin-verwuester.png",
    beschreibung: [
      "In der Gesellschaft der Hobgoblins ist die Akademie der Verwüstung dafür verantwortlich, Hobgoblins mit magischem Talent aufzuspüren und auszubilden. Anwärter durchlaufen ein hartes Training, das ihnen die Fähigkeit verleiht, Feuerbälle und andere zerstörerische Magie für ihre Heerschar zu wirken. Ein Hobgoblin-Verwüster auf dem Schlachtfeld ist gleichermaßen ein Segen für seine Verbündeten wie eine Bedrohung für alle Feinde.",
      "Andere Kulturen mögen ihre Magier wie zurückgezogene Akademiker behandeln, Hobgoblins erwarten von den ihren, dass sie kämpfen. Verwüster lernen die Grundlagen der Kampfkunst und messen ihre Taten an der Anzahl besiegter Gegner.",
      "Sie genießen den Respekt der anderen Mitglieder ihrer Heerschar, und viele begegnen ihnen mit unterwürfigem Gehorsam. Ihre Fähigkeit, ganze Schlachtreihen mit einem einzigen Zauber zu vernichten, ermöglicht ihnen, im Kampf viel mehr Ruhm zu sammeln, als es einem gewöhnlichen Krieger je möglich wäre. Manch ein Volk könnte das als Abkürzung zum Ruhm betrachten, doch unter Hobgoblins wird die Gabe der Magie hochgeschätzt und gilt als so nützlich und natürlich wie ein starker Schwertarm oder taktische Brillanz. All dies sind Segen von Maglubiyet, die trainiert und in der Schlacht entfesselt werden müssen.",
      "Verwüster erlernen eine vereinfachte Version der Hervorrufungsmagie. Ihre Ausbildung umfasst nicht das theoretische Wissen, das andere Völker studieren. Dadurch sind sie zwar im Kampf mächtig, aber relativ unwissend, was die Details darüber angeht, wie und warum ihre Magie funktioniert.",
      "Die Akademie der Verwüstung glaubt, dass eine akademische Herangehensweise an die Magie ein Zeichen von Schwäche und Ineffizienz ist. Ein Krieger muss nichts über Metallurgie wissen, um ein Schwert zu führen, warum sollte sich also ein Magier um die Quelle seiner magischen Macht scheren? Verwüster lieben es, ihre kämpferische Überlegenheit zu beweisen, indem sie gegnerische Zauberwirker aufsuchen und sie vernichten."
    ],
    besonderheiten: [
      { name: "Arkaner Vorteil", beschreibung: "Einmal pro Runde kann der Hobgoblin einer Kreatur mit einem Schadenszauber zusätzlich 7 (2W6) Punkte Schaden zufügen, wenn sich das Ziel innerhalb von 1,5 m um einen Verbündeten des Hobgoblins befindet, der nicht kampfunfähig ist." },
      { name: "Arkanes Wissen der Armee", beschreibung: "Wenn der Hobgoblin einen Zauber wirkt, der Schaden verursacht oder eine Kreatur zwingt, einen Rettungswurf abzulegen, kann er bestimmen, dass er und eine beliebige Anzahl von Verbündeten immun gegen den vom Zauber verursachten Schaden sind und ihnen der Rettungswurf automatisch gelingt." },
      { name: "Zauberwirken", beschreibung: "Der Hobgoblin ist ein Zauberwirker der 7. Stufe. Sein Attribut zum Zauberwirken ist Intelligenz (Zauberrettungswurf-SG 13, +5 zum Treffen mit Zauberangriffen). Er hat die folgenden Magierzauber vorbereitet: Zaubertricks (beliebig oft): Feuerpfeil, Kältestrahl, Säurespritzer, Schockgriff. 1. Grad (4 Zauberplätze): Donnerwoge, Magisches Geschoss, Nebelwolke. 2. Grad (3 Zauberplätze): Melfs Säurepfeil, Sengender Strahl, Windstoß. 3. Grad (3 Zauberplätze): Blitz, Feuerball, Fliegen. 4. Grad (1 Zauberplatz): Eissturm." }
    ],
    aktionen: [
      { name: "Kampfstab", beschreibung: "Nahkampf-Waffenangriff: +3 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 4 (1W6+1) Wuchtschaden, oder 5 (1W8+1) Wuchtschaden, wenn die Waffe mit beiden Händen geführt wird." }
    ],
