    tp_wuerfel: "9W8+18",
    bewegung: { "Gehen": "6 m", "Klettern": "6 m" },
    attribute: { STR: 16, DEX: 13, CON: 14, INT: 3, WIS: 10, CHA: 3 },
    rettungswuerfe: {},
    fertigkeiten: { "Heimlichkeit": 5, "Wahrnehmung": 2 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Blindsicht 18 m"],
    passiveWahrnehmung: 12,
    sprachen: [],
    umgebung: ["Höhle", "Unterirdisch"],
    bild: "assets/images/monster/almanach/hoehlenfischer.png",
    beschreibung: [
      "Ein Höhlenfischer ist ein unterirdisch lebendes arachnoides Tier mit langer Schnauze. In dieser befinden sich Drüsen, aus denen die Kreatur einen klebrigen Faden aussondert, mit dem sie wie eine Spinne Beute fängt.",
      "Ein Höhlenfischer jagt für gewöhnlich kleine Tiere, besonders Fledermäuse, indem er Fäden über Öffnungen spannt, durch die sich die Beute bewegen könnte. Dann klettert er zu einem Versteck, ruht sich aus und wartet. Wenn ein Opfer in den Faden stolpert, holt der Höhlenfischer seine Mahlzeit ein. Eine Gruppe der Kreaturen könnte gemeinsam ein großes Gebiet mit Fäden überziehen, doch sobald eine potenzielle Nahrungsquelle gefangen ist, kämpfen die Höhlenfischer um die Beute. Gelingt es einem Opfer, dem anfänglichen Hinterhalt zu entkommen, schießen Höhlenfischer Fäden auf ihre Beute, um sie einzufangen.",
      "Nahrungsknappheit könnte eine Gruppe Höhlenfischer an die Oberfläche locken, in ein schattiges Tal oder einen düsteren Wald, wo die Kreaturen nicht nur auf einheimische Beutetiere, sondern auch auf Entdecker oder Reisende stoßen können. Ein Höhlenfischer weiß instinktiv, dass größere Ziele wie Humanoide schwierige Beute sind, und vermeidet es, diese anzugreifen, sofern es sich nicht um ein einzelnes Ziel handelt. Die Kreatur könnte versuchen, einen Kundschafter zu töten, der sich in einiger Entfernung zu den übrigen Reisenden bewegt, oder einen Nachzügler, doch sie wird nicht die ganze Gruppe attackieren.",
      "Hat man einen Höhlenfischer erschlagen, lässt sich so gut wie jedes Teil von ihm verwerten. Sein Blut enthält Alkohol und schmeckt wie starker Likör. Mehrere Zwergenschnäpse basieren auf Höhlenfischerblut als Teil des Rezepts, und einige Zwerge, besonders die Berserker, trinken es pur. Sammelt man die Fäden der Kreatur, lassen sie sich zu einem Seil weben, das dünn, fest und so gut wie unsichtbar ist. Höhlenfischerfleisch ist essbar und schmeckt wie Krabbe, die in starkem Wein gekocht wurde. Sein Panzer kann zur Herstellung von Werkzeugen, Rüstungen und Schmuck verwendet werden.",
      "Während einige Leute Höhlenfischer wegen ihrer Fäden und ihres Bluts jagen, sammeln andere die Eier aus dem Gelege der Kreatur und ziehen die Schlüpflinge auf. Höhlenfischer besitzen eine natürliche Abneigung gegen Feuer, da ihr Blut brennbar ist. Deshalb nutzen Spinnenelfen und Hobgoblins manchmal Fackeln und glühende Schüreisen, um Höhlenfischer mit der Androhung von Gewalt als Wachttiere oder Kriegsbestien auszubilden."
    ],
    besonderheiten: [
      { name: "Klebriger Faden", beschreibung: "Der Höhlenfischer kann seine Aktion verwenden, um einen bis zu 18 m langen, klebrigen Faden zu verschießen, der an allem haftet, was er berührt. Eine Kreatur, die am Faden gefangen ist, wird vom Höhlenfischer gepackt (SG 13 zum Entkommen). Attributswürfe, um zu entkommen, sind im Nachteil. Der Faden kann angegriffen werden (RK 15; 5 Trefferpunkte; immun gegen Giftschaden und psychischen Schaden), doch wenn der verursachte Schaden nicht ausreicht, um ihn zu durchtrennen, bleibt die Waffe kleben. Dann sind eine Aktion und ein erfolgreicher Stärkewurf gegen SG 13 nötig, um sie loszureißen. Den Faden zu zerstören, fügt dem Höhlenfischer keinen Schaden zu, und er kann im nächsten Zug einen neuen verschießen." },
      { name: "Brennbares Blut", beschreibung: "Werden die Trefferpunkte des Höhlenfischers auf die Hälfte oder weniger reduziert, erhält er eine Anfälligkeit gegenüber Feuerschaden." },
      { name: "Spinnenklettern", beschreibung: "Der Höhlenfischer kann schwierige Oberflächen erklimmen und sogar kopfüber an der Decke hängen, ohne einen Attributswurf machen zu müssen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Höhlenfischer führt zwei Angriffe mit seinen Klauen aus." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 10 (2W6+3) Hiebschaden." },
      { name: "Faden", beschreibung: "Eine Kreatur, die vom haftenden Faden des Höhlenfischers gepackt wird und 200 Pfund oder weniger wiegt, muss einen Stärkerettungswurf gegen SG 13 ablegen. Bei einem Misserfolg wird das Ziel in einen freien Bereich innerhalb von 1,5 m zum Höhlenfischer gezogen und dieser führt als Bonusaktion einen Klauenangriff gegen die Kreatur durch. Das Heranziehen des Ziels befreit alle anderen Kreaturen, die an dem Faden haften. Solange er das Ziel mit seinem Faden gepackt hat, kann der Höhlenfischer keinen neuen Faden verschießen." }
    ],
