    bild: "assets/images/monster/almanach/kind_der_tiefe.png",
    beschreibung: [
      "Kinder der Tiefe begannen ihr Leben als Menschen, die von der Küste geraubt oder von einem sinkenden Schiff gerettet wurden und denen eine Macht unter der See einen schrecklichen Handel anbot: Ergebe dich mir mit Körper und Seele oder ertrinke. Wer das Angebot annimmt, wird einem uralten Ritual unterzogen, das unter bösen Kreaturen der Meere weitverbreitet ist. Es ist schmerzhaft und das Ergebnis niemals sicher, aber wenn es funktioniert, verwandelt es die luftatmende Person in einen Gestaltwandler, der eine Form anzunehmen vermag, die sich unter den Wellen vollständig zu Hause fühlt.",
      "Ein Kind der Tiefe verlässt das Meer im Dienste seines Meisters, vermutlich einem Kraken oder einem anderen uralten Wesen der Tiefe. Auch wenn der Gestaltwandler den Verstand und Körper der Person, die er einmal war, als eine Art Maske trägt, verfolgt er kein anderes Ziel, als die Wünsche seines Meisters zu erfüllen. Manchmal kehrt ein Kind der Tiefe in seine frühere Heimat zurück, wo es freudig willkommen geheißen wird, da die geliebte Person wider aller Wahrscheinlichkeit noch am Leben zu sein scheint, obwohl alle Hoffnung bereits verloren war. Manchmal nimmt die Kreatur auch eine neue Identität an. Auf jeden Fall ist es ihre Pflicht, die Welt der Luftatmer zu infiltrieren und ihrem neuen Meister Bericht zu erstatten. Seiner Aufgabe folgend, schleicht sich das Kind der Tiefe ins Leben eines arglosen Feindes und gibt sich als neuer bester Freund, unwiderstehlicher Liebhaber, perfekter Kandidat für eine Arbeit oder als eine andere Rolle aus, die es ihm erlaubt, die Befehle seines Meisters auszuführen.",
      "Die Ausbildung, die ein Kind der Tiefe durchläuft, raubt ihm jedes Mitgefühl für jene, die es ausspioniert. Auch wenn sich die Kreatur verliebt benehmen kann, über den Witz eines Freundes lachen oder zornig über eine Ungerechtigkeit sein mag, ist dies für sie nur ein Mittel zum Zweck. Sie glaubt, dass ihre wahre Gestalt die Form ist, die sie annimmt, wenn sie ins Meer zurückkehrt, das sie nun Heimat nennt. Ironischerweise jedoch verliert ein Kind der Tiefe, das in Fischgestalt getötet wird, die Magie, die es korrumpierte, sodass nur die Leiche der Person zurückbleibt, welche die Kreatur einmal war."
    ],
    besonderheiten: [
      { name: "Gestaltwandler", beschreibung: "Das Kind der Tiefe kann seine Aktion verwenden, um sich in eine Hybridgestalt aus Humanoiden und Fisch oder zurück in seine wahre Gestalt zu verwandeln. Abgesehen von seiner Bewegungsrate sind seine Spielwerte in jeder Gestalt gleich. Ausrüstung, die es trägt oder in der Hand hält, wird nicht verwandelt. Das Kind der Tiefe nimmt wieder seine wahre Gestalt an, wenn es stirbt." },
      { name: "Amphibisch (nur Hybridgestalt)", beschreibung: "Das Kind der Tiefe kann Luft und Wasser atmen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "In humanoider Gestalt führt das Kind der Tiefe zwei Nahkampfangriffe durch; in Hybridgestalt drei Nahkampfangriffe: einen mit seinem Biss und zwei mit seinen Klauen." },
      { name: "Streitaxt (nur humanoide Gestalt)", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 8 (1W8+4) Hiebschaden, oder 9 (1W10+4) Hiebschaden, wenn die Waffe mit beiden Händen geführt wird." },
      { name: "Biss (nur Hybridgestalt)", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 6 (1W4+4) Stichschaden." },
      { name: "Klaue (nur Hybridgestalt)", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 7 (1W6+4) Hiebschaden." },
      { name: "Psychisches Kreischen (nur Hybridgestalt; Aufladung nach einer kurzen oder langen Rast)", beschreibung: "Das Kind der Tiefe stößt einen schrecklichen Schrei aus, der bis zu 90 m weit hörbar ist. Jeder Kreatur innerhalb von 9 m muss ein Weisheitsrettungswurf gegen SG 13 gelingen, um nicht bis zum Beginn des nächsten Zugs des Kinds der Tiefe betäubt zu sein. Im Wasser überträgt das psychische Kreischen auch die Erinnerungen der letzten 24 Stunden an den Meister, unabhängig von der Entfernung, solange sich das Kind der Tiefe und der Meister in demselben Gewässer befinden." }
    ],
