    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 7, DEX: 15, CON: 12, INT: 8, WIS: 7, CHA: 8 },
    rettungswuerfe: {},
    fertigkeiten: { "Wahrnehmung": 0 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
