    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Gemeinsprache", "Drakonisch"],
    umgebung: [],
    bild: "assets/images/monster/almanach/kobold-erfinder.png",
    beschreibung: [
      "Ein Kobold-Erfinder ist schlau und geschickt mit seinen Händen. Er baut neuartige, improvisierte Waffen in der Hoffnung, im Kampf einen ungeahnten Vorteil zu erlangen. Ein Erfinder fängt Käfer, sammelt exotische Schleime in Gewölben und beansprucht die besten gestohlenen Güter als Zutaten für seine Experimente. Seine Kreationen sehen manchmal seltsam aus, aber wie die Fallen der Kobolde funktionieren sie viel besser, als ihre Materialien vermuten lassen.",
      "Die neuen Waffen eines Erfinders überstehen meist nur ein oder zwei Angriffe, ehe sie in ihre Einzelteile zerfallen, aber in dieser kurzen Zeit können sie erstaunlich effektiv sein. Die meisten Erfinder sind geschickt genug, dass sie sich nicht selbst mit ihren Gerätschaften verletzen, andere jedoch sind nicht mit diesem Talent gesegnet. Die Waffen müssen nicht tödlich sein. Oft ist es ihr Zweck, eine Kreatur lange genug abzulenken, einzuschüchtern oder zu verwirren, damit andere Kobolde den Gegner überwältigen können. In einer Begegnung stehen einem Erfinder für gewöhnlich ein oder zwei improvisierte Waffen zur Verfügung."
    ],
    besonderheiten: [
      { name: "Rudeltaktik", beschreibung: "Der Kobold ist im Vorteil bei Angriffswürfen gegen eine Kreatur, wenn sich mindestens ein Verbündeter des Kobolds innerhalb von 1,5 m zur Kreatur befindet und nicht kampfunfähig ist." },
      { name: "Empfindlichkeit gegenüber Sonnenlicht", beschreibung: "Solange sich der Kobold im Sonnenlicht befindet, ist er im Nachteil bei Angriffswürfen sowie Würfen auf Weisheit (Wahrnehmung), die sich aufs Sehen beziehen." }
    ],
    aktionen: [
      { name: "Dolch", beschreibung: "Nahkampf- oder Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5 m oder Reichweite 6/18 m, ein Ziel. Treffer: 4 (1W4+2) Stichschaden." },
      { name: "Schleuder", beschreibung: "Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 9/36 m, ein Ziel. Treffer: 4 (1W4+2) Wuchtschaden." },
      { name: "Waffenerfindung", beschreibung: "Der Kobold verwendet einen der folgenden Angriffe (bestimme mit einem W8 oder wähle aus), von denen er jeden nur einmal am Tag einsetzen kann. 1. Säure: Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5/6 m, ein Ziel. Treffer: 7 (2W6) Säureschaden. 2. Alchemistenfeuer: Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5/6 m, ein Ziel. Treffer: 2 (1W4) Feuerschaden zu Beginn eines jeden Zugs des Ziels. Eine Kreatur kann den Schaden beenden, indem sie eine Aktion verwendet und einen erfolgreichen Geschicklichkeitswurf gegen SG 10 ablegt, um die Flammen zu löschen. 3. Korb voller Tausendfüßler: Der Kobold wirft einen Korb in einen quadratischen Bereich mit 1,5 m Seitenlänge innerhalb von 6 m. Ein Schwarm von Insekten (Tausendfüßler) mit 11 Trefferpunkten windet sich aus dem Korb und würfelt auf Initiative. Am Ende eines jeden Zugs des Schwarms besteht eine Chance von 50 %, dass er sich auflöst. 4. Topf mit grünem Schleim: Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5/6 m, ein Ziel. Treffer: Das Ziel wird von einem Fleck grünen Schleims bedeckt (siehe Kapitel 5 des Dungeon Master's Guide). Fehlschlag: Ein Fleck grünen Schleims bedeckt einen zufällig bestimmten quadratischen Bereich mit 1,5 m Seitenlänge an der Wand oder dem Fußboden. 5. Topf mit Fäulnismaden: Der Kobold wirft einen Lehmtopf in einen quadratischen Bereich mit 1,5 m Seitenlänge innerhalb von 6 m. Das Gefäß zerbricht beim Aufprall. Ein Schwarm von Fäulnismaden windet sich aus dem geborstenen Topf und bedroht den quadratischen Bereich. 6. Skorpion am Stiel: Nahkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 1 Stichschaden, und das Ziel muss einen Konstitutionsrettungswurf gegen SG 9 ablegen. Bei einem Misserfolg erleidet es 4 (1W8) Giftschaden oder die Hälfte bei einem erfolgreichen Rettungswurf. 7. Stinktier im Käfig: Der Kobold befreit ein Stinktier in einem unbesetzten Bereich innerhalb von 1,5 m. Das Stinktier besitzt eine Bewegungsrate von 6 m, RK 10, 1 Trefferpunkt und keine direkten Angriffe. Es würfelt auf Initiative und verwendet die Aktion in seinem Zug, um ein Sekret auf eine zufällige Kreatur innerhalb von 1,5 m zu versprühen. Das Ziel muss einen Konstitutionsrettungswurf gegen SG 9 ablegen. Bei einem Misserfolg beginnt es zu würgen und kann für 1 Minute keine Aktionen ausführen. Das Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt bei einem Erfolg beenden. Eine Kreatur, die nicht atmen muss oder immun gegen Gift ist, ist bei dem Rettungswurf automatisch erfolgreich. Sobald das Stinktier sein Sekret versprüht hat, kann es dies erst wieder nach einer langen oder kurzen Rast tun. 8. Wespennest im Beutel: Der Kobold wirft einen kleinen Beutel in einen quadratischen Bereich mit 1,5 m Seitenlänge innerhalb von 6 m. Ein Schwarm von Insekten (Wespen) mit 11 Trefferpunkten entsteigt dem Beutel und würfelt auf Initiative. Am Ende eines jeden Zugs des Schwarms besteht eine Chance von 50 %, dass er sich auflöst." }
    ],
