    bild: "assets/images/monster/almanach/kobold-schuppenzauberer.png",
    beschreibung: [
      "Ein Schuppenzauberer besitzt ein angeborenes Talent für arkane Magie, was ihn zu einem sehr wertvollen Mitglied des Stammes macht, und das aus mehreren Gründen. Weil die Gottheit der Kobolde noch immer eingesperrt ist, gibt es in den meisten Stämmen niemanden, der göttliche Magie zu nutzen vermag. Daher erfüllen die Schuppenzauberer die Rolle des Ratgebers und Traditionsbewahrers. In Zeiten des Friedens nutzen sie ihre Zauber, um den Bau zu verstärken und zu verbessern und die anderen Kobolde zu unterstützen. Wenn der Stamm bedroht wird, greift der Schuppenzauberer seine Feinde mit Feuer und Gift an, spart sich aber stets etwas Magie für sich selbst auf, falls er fliehen muss oder einen Häscher überrumpeln will.",
      "In einem Koboldstamm, der mit einem Drachen verbündet ist – für gewöhnlich einem, der in der Nähe eines Drachenhortes lebt –, dient der Schuppenzauberer auch als Diplomat und Sprachrohr. Er sieht die Wünsche des gewaltigen Echsenwesens vorher, gibt anderen Kobolden Befehle in dessen Namen und erstattet ihm Bericht. Wie jeder einfache Kobold begegnet auch der Zauberer dem Drachen mit Ehrfurcht und Respekt, aber er weiß, dass seine Pflicht es erforderlich macht, diesen nicht die ganze Zeit nur anzubeten. Er versteht auch, dass die häufige Nähe zu der mächtigen Kreatur bedeutet, dass er vermutlich als Erster stirbt, wenn sein Meister zornig oder ungehalten wird. Daher versucht er verzweifelt, ein Gleichgewicht zwischen Bewunderung und Schrecken in seinem Verhalten gegenüber dem Drachen zu finden."
    ],
    besonderheiten: [
      { name: "Zauberwirken", beschreibung: "Der Kobold ist ein Zauberwirker der 3. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 12, +4 zum Treffen mit Zauberangriffen). Er hat die folgenden Zauber aus der Liste des Zauberers vorbereitet: Zaubertricks (beliebig oft): Ausbessern, Feuerpfeil, Gift versprühen, Magierhand; 1. Grad (4 Zauberplätze): Chromatische Kugel, Person bezaubern, Rascher Rückzug; 2. Grad (2 Zauberplätze): Sengender Strahl." },
      { name: "Zaubereipunkte", beschreibung: "Der Kobold verfügt über 3 Zaubereipunkte. Verbrauchte Punkte erhält er nach Abschluss einer langen Rast zurück. Er kann Zaubereipunkte für die folgenden Vorzüge aufwenden: Konzentrierter Zauber: Wenn der Kobold einen Zauber wirkt, der eine Kreatur zu einem Rettungswurf zwingt, um dem Effekt zu widerstehen, kann er 3 Zaubereipunkte ausgeben, damit das Ziel bei seinem ersten Rettungswurf gegen den Zauber im Nachteil ist. Subtiler Zauber: Wenn der Kobold einen Zauber wirkt, kann er 1 Zaubereipunkt ausgeben, um den Zauber ohne Gesten oder verbale Komponenten zu wirken." },
      { name: "Rudeltaktik", beschreibung: "Der Kobold ist im Vorteil bei Angriffswürfen gegen eine Kreatur, wenn sich mindestens ein Verbündeter des Kobolds innerhalb von 1,5 m zur Kreatur befindet und nicht kampfunfähig ist." },
      { name: "Empfindlichkeit gegenüber Sonnenlicht", beschreibung: "Solange sich der Kobold im Sonnenlicht befindet, ist er im Nachteil bei Angriffswürfen sowie Würfen auf Weisheit (Wahrnehmung), die sich aufs Sehen beziehen." }
    ],
    aktionen: [
      { name: "Dolch", beschreibung: "Nahkampf- oder Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5 m oder Reichweite 6/18 m, ein Ziel. Treffer: 4 (1W4+2) Stichschaden." }
    ],
