    rk: 17,
    ruestungstyp: "natürliche Rüstung",
    tp: 102,
    tp_wuerfel: "12W6+60",
    bewegung: { "Gehen": "9 m", "Graben": "9 m" },
    attribute: { STR: 23, DEX: 14, CON: 20, INT: 10, WIS: 15, CHA: 9 },
    rettungswuerfe: {},
    fertigkeiten: { "Athletik": 9, "Heimlichkeit": 5, "Wahrnehmung": 5 },
    schadensresistenzen: ["Wucht-, Stich- und Hiebschaden durch nicht-magische Angriffe"],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 36 m", "Erschütterungssinn 36 m"],
    passiveWahrnehmung: 15,
    sprachen: ["Zwergisch", "Gnomisch", "Sylvanisch", "Terral", "Gemeinsprache der Unterreiche"],
    umgebung: [],
    bild: "assets/images/monster/almanach/korred.png",
    beschreibung: [
      "Korreds sind unvorhersehbare, geheimnistuerische Feenwesen mit einer starken Verbindung zu Erde und Stein. Aufgrund ihrer magischen Haare und ihres mythischen Verständnisses für Mineralien werden sie oft von Schatzjägern, Zwergen und anderen aufgesucht, denen es nach den Kostbarkeiten der Erde verlangt.",
      "Korreds bleiben lieber unter sich und lassen sich nur manchmal mit Kreaturen der elementaren Erde wie Galeb Duhr ein. Ein Stamm der kleinen Feenwesen versammelt sich wöchentlich, um zeremonielle Tänze aufzuführen und mit Hufen und Keulen Rhythmen auf den Stein zu schlagen. In den Tiefen der Erde flüchten Korreds für gewöhnlich vor anderen Kreaturen, aber sie verhalten sich aggressiver, wenn sie sich beleidigt fühlen oder die Geräusche von Bergarbeiten sie stören.",
      "Niemand kennt die Weise des Steins und der Erde besser als ein Korred. Scheinbar ist ihr Volk sogar in der Lage, Metalladern oder Edelsteine zu riechen. Ein Korred an der Oberfläche kann spüren, wo sich das Grundgestein hebt und senkt und wo Höhlen liegen. Unter der Erde kennt er meilenweit alle Wege durch den Fels. Geheimtüren, die durch Stein führen, sind für einen Korred so offensichtlich wie ein Fenster.",
      "Die kleinen Kreaturen vermögen Felsbrocken zu schleudern, die viel schwerer sind, als es für ihre geringe Körpergröße möglich scheint. Außerdem sind sie in der Lage, Steine zu formen, als seien sie Lehm, durch Felsen zu schwimmen und Erdelementare und andere Kreaturen zu beschwören. Sie besitzen eine übernatürliche Stärke, solange sie den Boden berühren.",
      "Zwar wachsen einem Korred am ganzen Körper Haare, aber nur die auf seinem Kopf sind magisch. Wenn sie geschnitten werden, verwandeln sie sich in das Material, das sie abgetrennt hat. Korreds schneiden ihr Haar mit Eisenscheren und nutzen die so erzeugten Stränge, um eiserne Seile zu weben, die sie magisch manipulieren können. Sie beleben sie zum Beispiel, um Kreaturen oder Gegenstände zu umschlingen und zu fesseln. Korreds sind sehr stolz auf ihr Haar und sind besonders erzürnt, wenn es jemand ohne ihre Erlaubnis abschneiden möchte."
    ],
    besonderheiten: [
      { name: "Haar befehligen", beschreibung: "Der Korred trägt ein mindestens 15 m langes eisernes Seil bei sich, das er aus seinen abgeschnittenen Haaren geflochten hat. Als Bonusaktion kann er einem solchen Seil innerhalb von 9 m befehlen, sich bis zu 6 m weit zu bewegen und eine Kreatur der Größenkategorie Groß oder kleiner, die der Korred sehen kann, zu umschlingen. Das Ziel muss einen erfolgreichen Geschicklichkeitsrettungswurf gegen SG 13 ablegen, um nicht von dem Seil gepackt zu werden (SG 13 zum Entkommen). Bis der Haltegriff endet, ist das Ziel festgesetzt. Der Korred kann eine Bonusaktion verwenden, um ein Ziel freizulassen. Es wird ebenfalls befreit, wenn der Korred stirbt oder kampfunfähig wird. Ein Seil aus Korred-Haar besitzt 20 Trefferpunkte und RK 20. Es erhält zu Beginn eines jeden Zugs des Korred 1 Trefferpunkt zurück, solange es noch mindestens 1 TP besitzt und der Korred am Leben ist. Wird das Seil auf 0 Trefferpunkte reduziert, ist es zerstört." },
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Korred ist Weisheit (Zauberrettungswurf-SG 13). Er kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Einswerden mit der Natur, Mit Stein verschmelzen, Stein formen; 1/Tag jeweils: Elementar beschwören (wie ein Zauber des 6. Grades; nur Galeb Duhr, Gargyl, Erdelementar oder Xorn), Ottos Unwiderstehlicher Tanz." },
      { name: "Steintarnung", beschreibung: "Der Korred ist im Vorteil bei Würfen auf Geschicklichkeit (Heimlichkeit), um sich in felsigem Gelände zu verstecken." },
      { name: "Stärke des Steins", beschreibung: "Solange er den Boden berührt, verursacht der Korred mit seinen Waffenangriffen zwei zusätzliche Würfel Schaden (siehe die Angaben bei den Angriffen)." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Korred führt zwei Angriffe mit seinem Zweihandknüppel aus oder schleudert zwei Felsen." },
      { name: "Zweihandknüppel", beschreibung: "Nahkampfwaffenangriff: +9 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 10 (1W8+6) Wuchtschaden, oder 19 (3W8+6) Wuchtschaden, wenn der Korred den Boden berührt." },
      { name: "Felsen", beschreibung: "Fernkampfwaffenangriff: +9 zum Treffen, Reichweite 18/36 m, ein Ziel. Treffer: 15 (2W8+6) Wuchtschaden, oder 24 (4W8+6) Wuchtschaden, wenn der Korred den Boden berührt." }
    ],
    bonusaktionen: [],
