    bild: "assets/images/monster/almanach/krakenpriester.png",
    beschreibung: [
      "Ein Kraken kann für Personen, die seinen Zorn miterleben mussten, gottgleich erscheinen. Wer die Stärke der Kreatur mit göttlicher Macht verwechselt oder sie durch Anbetung besänftigen will, wird manchmal von ihr mit Fähigkeiten belohnt und dient ihr fortan als Botschafter ihres Willens.",
      "Der Kraken kann sich die Gedanken des Priesters vage bewusst machen, wenn sich beide auf derselben Existenzebene befinden, und dann dessen Persönlichkeit beeinflussen und kontrollieren. Krakenpriester fungieren als Augen und Ohren ihrer Meister, und auch als Sprachrohr, wenn das urtümliche Monster beschließt, sich mitzuteilen.",
      "Jeder Priester durchläuft eine Veränderung des Aussehens, die den Einfluss des Kraken widerspiegelt, auch wenn sich dessen Anbetung auf unterschiedliche Arten manifestiert. Ein Krakenpriester könnte tintenschwarze Augen und einen Tentakel mit Saugnäpfen anstelle einer Zunge besitzen, ein anderer ein vollkommen glattes Gesicht ohne Sinnesorgane und einen Körper, der von Augen und Mündern bedeckt ist, aus denen Seewasser tropft. Diese grauenhaften Ausprägungen werden stärker, wenn der Kraken von seinem Lakaien Besitz ergreift, um seine schrecklichen Botschaften zu verkünden."
    ],
    besonderheiten: [
      { name: "Amphibisch", beschreibung: "Der Krakenpriester kann Luft und Wasser atmen." },
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Krakenpriester ist Weisheit (Zauberrettungswurf-SG 13, +5 zum Treffen mit Zauberangriffen). Er kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Befehl, Wasser erschaffen oder zerstören. Jeweils 3/Tag: Auf Wasser gehen, Dunkelheit, Wasser atmen, Wasser kontrollieren. Jeweils 1/Tag: Blitze herbeirufen, Evards Schwarze Tentakel." }
    ],
    aktionen: [
      { name: "Donnernde Berührung", beschreibung: "Nahkampf-Zauberangriff: +5 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 27 (5W10) Schallschaden." },
      { name: "Stimme des Kraken (Aufladung nach einer kurzen oder langen Rast)", beschreibung: "Ein Kraken spricht mit gewaltiger Stimme durch den Priester, was auf 90 m hörbar ist. Kreaturen nach Wahl des Priesters, die die Worte des Kraken hören können (gesprochen auf Abyssisch, Infernalisch oder Urtümlich), müssen einen erfolgreichen Charismarettungswurf gegen SG 14 ablegen, um nicht für 1 Minute verängstigt zu werden. Ein verängstigtes Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt auf ihm bei einem Erfolg beenden." }
    ],
