    bewegung: { "Gehen": "12 m" },
    attribute: { STR: 26, DEX: 12, CON: 22, INT: 15, WIS: 16, CHA: 17 },
    rettungswuerfe: { KON: 10, INT: 6, CHA: 7 },
    fertigkeiten: { "Fingerfertigkeit": 9, "Motiv erkennen": 7, "Täuschen": 11, "Wahrnehmung": 7 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: [],
    passiveWahrnehmung: 17,
    sprachen: ["Gemeinsprache", "Riesisch"],
