    bild: "assets/images/monster/almanach/laechelnder_der_wolkenriesen.png",
    beschreibung: [
      "Eigentlich sind Wolkenriesen nicht besonders religiös. Sie dulden viele widersprüchliche Ideen über ihre Schutzgottheit Memnor. Die Lächelnden strapazieren diese Toleranz.",
      "Lächelnde sind Wolkenriesen, die Memnors Schläue und List mehr als alle anderen Eigenschaften ehren und nachahmen. Sie sind große Trickser, die Fingerfertigkeit, Täuschung, Ablenkungen und Magie nutzen, um reich zu werden. Auch besitzen sie ein Gespür für das Unvorhersehbare und einen bösartigen Sinn für Humor.",
      "Obwohl Wolkenriesen ein gewisses Maß an List und Täuschung erwarten, wenn sie mit anderen ihrer Art Umgang haben, überschreitet das Verhalten der Lächelnden die Grenzen des Anstands. Sie sagen und tun Dinge, die edlere Wolkenriesen als unter ihrer Würde betrachten.",
      "Lächelnde bekamen ihren Namen aufgrund der seltsamen zweigesichtigen Masken, die sie tragen. Das Lächeln der einen Hälfte sieht oft mehr wie ein zynisches Grinsen oder ein triumphierendes Hohnlächeln aus als freundlich. Die finster blickende Hälfte stellt das Missfallen dar, das die Lächelnden über ihren Platz im Ordning empfinden, da sie den Sturmriesen untergeordnet sind. Die Masken dienen als Symbole ihrer Hingabe, aber sie verbergen auch die wahren Emotionen des Trägers."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Riesen ist Charisma (Zauberrettungswurf-SG 15). Er kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Magie entdecken, Licht, Nebelwolke. Jeweils 3/Tag: Federfall, Fliegen, Nebelschritt, Telekinese. Jeweils 1/Tag: Gasförmige Gestalt, Wetterkontrolle." },
      { name: "Zauberwirken", beschreibung: "Der Riese ist ein Zauberwirker der 5. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 15, +7 zum Treffen mit Zauberangriffen). Der Riese hat die folgenden Bardenzauber vorbereitet: Zaubertricks (beliebig oft): Einfache Illusion, Gehässiger Spott, Taschenspielerei. 1. Grad (4 Zauberplätze): Lautloses Trugbild, Selbstverkleidung, Tashas Fürchterlicher Lachanfall, Wunden heilen. 2. Grad (3 Zauberplätze): Einflüsterung, Unsichtbarkeit. 3. Grad (2 Zauberplätze): Mächtiges Trugbild, Zungen." },
      { name: "Scharfer Geruchssinn", beschreibung: "Der Riese ist im Vorteil bei Würfen auf Weisheit (Wahrnehmung), die auf dem Geruchssinn basieren." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Riese führt zwei Angriffe mit seinem Morgenstern aus." },
      { name: "Morgenstern", beschreibung: "Nahkampf-Waffenangriff: +12 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 21 (3W8+8) Wuchtschaden. Der Angriff verursacht zusätzlich 14 (4W6) Punkte Schaden, wenn der Riese bei seinem Angriffswurf im Vorteil ist." },
      { name: "Felsen", beschreibung: "Fernkampf-Waffenangriff: +12 zum Treffen, Reichweite 18/72 m, ein Ziel. Treffer: 30 (4W10+8) Wuchtschaden. Der Angriff verursacht zusätzlich 14 (4W6) Punkte Schaden, wenn der Riese bei seinem Angriffswurf im Vorteil ist." },
      { name: "Gestaltwandel", beschreibung: "Der Riese verwandelt sich magisch in ein Tier oder einen Humanoiden, das oder den er gesehen hat, oder nimmt seine wahre Gestalt an. Jede Ausrüstung, die der Riese trägt oder in der Hand hält, verschmilzt mit der neuen Gestalt. Seine Spielwerte, abgesehen von der Größenkategorie, verändern sich nicht. Er nimmt seine wahre Gestalt an, wenn er stirbt." }
    ],
