    attribute: { STR: 21, DEX: 10, CON: 18, INT: 5, WIS: 7, CHA: 5 },
    rettungswuerfe: {},
    fertigkeiten: { "Wahrnehmung": 1 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Verängstigt"],
    sinne: [],
    passiveWahrnehmung: 11,
    sprachen: ["Riesisch"],
    umgebung: ["Grasland", "Hügel", "Wald"],
    bild: "assets/images/monster/almanach/mund_von_grolantor.png",
    beschreibung: [
      "Hügelriesen wissen, welches Essen sie fetter macht, und sie begreifen, dass sie dünner werden, wenn sie sich zu sehr anstrengen. Allerdings verstehen die faulen Rohlinge nicht, dass manche Dinge sie krank machen. Sie verschlingen verdorbene Nahrung und verweste Kadaver mit dem Enthusiasmus eines Kindes, das sich an einer Süßspeise erfreut. Zum Glück für die Hügelriesen verfügen sie über den Magen eines Aasfressers und leiden nur selten unter ihren Essgewohnheiten. Das macht es für sie umso geheimnisvoller, wenn einer von ihnen krank wird und kein Essen mehr bei sich behalten kann. Sich übergebende Hügelriesen werden als Überbringer einer Botschaft von Grolantor betrachtet.",
      "Der Klan trennt den Kranken von den anderen und sperrt ihn oft in einen Käfig oder bindet ihn an einem Pfosten fest. Ein Priester von Grolantor oder der Häuptling besucht den hungernden Riesen jeden Tag und versucht, Vorzeichen aus den Gallepfützen zu lesen, die der Leidende erbrochen hat. Vergeht die Krankheit schnell, kann sich der Riese wieder der Gemeinschaft anschließen. Wenn nicht, wird er ausgehungert, bis er den Verstand verliert, damit Grolantors Hunger durch einen Mund in der Welt gestillt werden kann.",
      "Ein Mund von Grolantor ist in der Gesellschaft der Hügelriesen so entrechtet, dass er nicht mehr als Person gilt, sondern als Objekt. Paradoxerweise wird dieses Objekt als heilige Verkörperung von Grolantors ewigem, quälendem Hunger betrachtet. Im Gegensatz zu den typischen dämlichen, trägen, halb eingeschlafenen Hügelriesen ist ein Mund von Grolantor gertenschlank, wachsam wie ein Raubvogel und immer in Bewegung – wenn er nicht wie die meiste Zeit eingesperrt oder angekettet ist. Gelingt es ihm, sich zu befreien, wird er ohne Frage einige Hügelriesen töten, ehe er zur Strecke gebracht werden kann oder in Mordlust davon rennt. Münder von Grolantor werden nur im Krieg, bei Überfällen auf feindliche Siedlungen oder als letzte Verteidigung zum Schutz des Stammes losgelassen. Wenn der Mund von Grolantor genug Feinde des Stammes abgeschlachtet und gefressen hat, verliert er zwischen den blutigen Überresten seiner Opfer das Bewusstsein, sodass er leicht wieder eingefangen werden kann."
    ],
    besonderheiten: [
      { name: "Mund des Wahnsinns", beschreibung: "Der Riese ist immun gegen den Zauber Verwirrung und ähnliche magische Effekte. In jedem seiner Züge nutzt der Hügelriese seine volle Bewegungsrate, um sich in Richtung der nächsten Kreatur zu bewegen oder etwas anderem, das er als Nahrungsquelle betrachtet. Bestimme seine Aktion zu Beginn des Zugs mit einem W10: 1–3: Der Riese führt drei Angriffe mit seinen Fäusten gegen ein zufälliges Ziel in Reichweite aus. Wenn sich keine Kreaturen in Reichweite befinden, verfällt der Riese in einen Kampfrausch und ist bis zum Ende seines nächsten Zugs im Vorteil bei Angriffswürfen. 4–5: Der Riese führt einen Angriff mit seinen Fäusten gegen jedes Ziel in Reichweite aus. Wenn keine Kreaturen in Reichweite sind, führt der Riese einen Faust-Angriff gegen sich selbst aus. 6–7: Der Riese führt einen Angriff mit seinem Biss gegen ein zufälliges Ziel in Reichweite aus. Wenn keine Kreaturen in Reichweite sind, werden seine Augen glasig und er ist bis zum Beginn seines nächsten Zugs betäubt. 8–10: Der Riese führt drei Angriffe gegen ein zufälliges Ziel in Reichweite aus: einen mit seinem Biss und zwei mit seinen Fäusten. Wenn sich keine Kreaturen in Reichweite befinden, verfällt der Riese in einen Kampfrausch und ist bis zum Ende seines nächsten Zugs im Vorteil bei Angriffswürfen." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 15 (3W6+5) Stichschaden, und der Riese erhält auf magische Weise Trefferpunkte in Höhe des verursachten Schadens zurück." },
      { name: "Faust", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 18 (3W8+5) Hiebschaden." }
    ],
