      "Neogi-Meister sind die ranghöchsten Mitglieder ihrer Gesellschaft und dienen als Anführer, Diplomaten und Händler. Neogi kennzeichnen sich und ihre Sklaven mit Farben, Tätowierungen und mit Hilfe von Verwandlungsmagie, um Rang, Leistungen und Besitz anzuzeigen. An diesen Zeichen kann jedes Mitglied der Gemeinschaft seine Vorgesetzten erkennen, deren Willen er sich strikt zu beugen hat, wenn er nicht hart bestraft werden will."
