    bild: "assets/images/monster/almanach/neothelid.png",
    beschreibung: [
      "Ein Neothelid ist ein schleimbedeckter Wurm von gewaltiger Größe. Er entsteht, wenn der Fortpflanzungskreislauf der Gedankenschinder unterbrochen wird. In seltenen Fällen geht eine Illithidenkolonie zu Grunde, für gewöhnlich nach einem Angriff von außen, und das Ältestengehirn stirbt oder wird getötet. In einem solchen Fall sind die Kaulquappen plötzlich ohne Aufsicht und Pflege und werden entsprechend nicht mehr gefüttert. Getrieben von Hunger beginnen sie einander zu verschlingen. Ein Prozess, den nur eine einzige Kaulquappe von den Tausenden der Kolonie überlebt und der sie als Neothelid dem Laichbecken entsteigen lässt.",
      "Zu den stärksten Tabus der Gesellschaft der Illithiden gehört es, eine erwachsene Kaulquappe am Leben zu lassen, ohne sie in ein Spendergehirn einzusetzen. Unter normalen Umständen wird jede Kaulquappe, die zu einer Größe von mehr als einigen Zentimetern heranwächst, sofort vom Ältestengehirn getötet und dient als Nahrung für dieses oder seine weniger reifen Geschwister. Jede Kaulquappe, die der Selektion aus irgendeinem Grund entgeht und überlebt, wird als Gefahr für die Kolonie betrachtet – und die Gedankenschinder organisieren Jagdgruppen, um das Monstrum zu vernichten. Da Neotheliden nicht intelligent genug sind, dass die telepathische Macht des Ältestengehirns sie wahrnehmen kann, sind solche harten Vorsichtsmaßnahmen notwendig.",
      "Neotheliden sind wilde Kreaturen, die nichts kennen außer ihren raubtierartigen Instinkten, die sie bislang leiteten. Sie haben Schwierigkeiten, ihre neuen psionischen Fähigkeiten zu begreifen. Auf der Suche nach mehr Gehirnen, um ihren ewigen Hunger zu stillen, durchstreifen die Wesen unterirdische Tunnel und werden zunehmend gewalttätiger. Neotheliden sind in der Lage, aus ihren Tentakeldrüsen Enzyme zu versprühen, die Gewebe zersetzen, ihre Opfer in Schleimpfützen verwandeln und nur das pulsierende Gehirn unbeschadet zurücklassen. Da sie ihre Verbindung zu den Illithiden nicht einmal im Ansatz verstehen, greifen sie diese ebenso wahrscheinlich an wie alles andere auch."
    ],
    besonderheiten: [
      { name: "Kreaturensinn", beschreibung: "Der Neothelid ist sich der Präsenz jeder Kreatur innerhalb von 1,5 km bewusst, wenn diese einen Intelligenzwert von 4 oder höher besitzt. Es kennt die Entfernung und Richtung zu jeder Kreatur sowie ihren Intelligenzwert, kann aber nicht mehr als das spüren. Eine Kreatur, die von Gedankenleere, Unauffindbarkeit oder ähnlicher Magie geschützt wird, kann auf diese Weise nicht wahrgenommen werden." },
      { name: "Angeborenes Zauberwirken (Psionik)", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Neotheliden ist Weisheit (Zauberrettungswurf-SG 16). Er kann angeboren die folgenden Zauber wirken, wobei keine Komponenten nötig sind: Beliebig oft: Schweben; 1/Tag jeweils: Schwachsinn, Telekinese, Verwirrung." },
      { name: "Magieresistenz", beschreibung: "Der Neothelid ist im Vorteil bei Rettungswürfen gegen Zauber und andere magische Effekte." }
    ],
    aktionen: [
      { name: "Tentakel", beschreibung: "Nahkampfwaffenangriff: +13 zum Treffen, Reichweite 4,5 m, ein Ziel. Treffer: 21 (3W8+8) Wuchtschaden plus 13 (3W8) psychischer Schaden. Ist das Ziel eine Kreatur der Größenkategorie Groß oder kleiner, muss es einen erfolgreichen Stärkerettungswurf gegen SG 21 ablegen, um nicht vom Neotheliden verschlungen zu werden. Eine verschluckte Kreatur ist blind und festgesetzt, hat vollständige Deckung gegen Angriffe und andere Effekte von außerhalb des Neotheliden und erleidet 35 (10W6) Punkte Säureschaden zu Beginn eines jeden Zugs des Neotheliden. Wenn das Monster in einem Zug 30 oder mehr Punkte Schaden durch eine Kreatur in seinem Inneren erleidet, muss ihm am Ende des Zugs ein Konstitutionsrettungswurf gegen SG 18 gelingen, um nicht alle verschluckten Kreaturen hochzuwürgen. Hochgewürgte Kreaturen landen liegend in einem Bereich innerhalb von 3 m um den Neotheliden. Stirbt das Monster, sind verschluckte Kreaturen nicht länger festgesetzt und können 6 m ihrer Bewegungsrate verwenden, um sich liegend aus dem Kadaver zu befreien." },
      { name: "Säureodem (Aufladung 5–6)", beschreibung: "Der Neothelid atmet Säure in einem Kegel von 18 m aus. Jede Kreatur in diesem Bereich muss einen Geschicklichkeitsrettungswurf gegen SG 18 ablegen. Bei einem Misserfolg erleidet ein Ziel 35 (10W6) Punkte Säureschaden oder die Hälfte bei einem erfolgreichen Rettungswurf." }
    ],
