    bewegung: { "Gehen": "9 m" },
    attribute: { STR: 8, DEX: 14, CON: 10, INT: 10, WIS: 8, CHA: 15 },
    rettungswuerfe: {},
    fertigkeiten: { "Heimlichkeit": 6 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
