    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 9,
    sprachen: ["Gemeinsprache", "Goblinisch"],
    umgebung: [],
    bild: "assets/images/monster/almanach/nilbog.png",
    beschreibung: [
      "Als Maglubiyet die Goblingötter unterwarf, ließ er nur Khurgorbaeyag am Leben, damit die Goblins unter der Knute des brutalen Aufsehers fügsam bleiben würden. Doch zu ihrem Pantheon gehörte auch ein Tricksergott, der entschlossen war, als Letzter zu lachen. Auch wenn seine Essenz von Maglubiyet zerschmettert wurde, überlebte der Gott in zersplitterter Form als Geist der Besessenheit. Bilden Goblinoide eine Heerschar, nimmt er Gestalt an, um in ihren Reihen für Chaos zu sorgen, wenn man ihn nicht besänftigt. Goblins besitzen keinen Namen für diese Gottheit und wagen es nicht, ihr einen zu geben, damit Maglubiyet ihn nicht nutzen kann, um den Gott zu fangen und zu zermalmen. Sie nennen den Geist und den Goblin, von dem er Besitz ergreift, einen Nilbog ('Goblin' rückwärts), und sie erfreuen sich an der Furcht, die er unter den Grottenschraten und Hobgoblins in der Heerschar verbreitet.",
      "Wenn Goblinoide eine Heerschar bilden, besteht die Chance, dass ein Goblin zu einem besessenen Nilbog wird, besonders wenn er von seinen Vorgesetzten misshandelt wurde. Diese Besessenheit verwandelt den Goblin in eine scherzende, verspielte Kreatur, die keine Strafen fürchtet. Sie besitzt die eigenartige Fähigkeit, andere dazu zu bringen, das Gegenteil von dem zu tun, was sie eigentlich wollten. Einen Nilbog anzugreifen, ist schlichtweg dumm, und ihn zu töten, lässt den Geist nur von einem anderen Goblin Besitz ergreifen. Man kann einen Nilbog nur dann hindern, Chaos zu stiften, indem man ihn gut behandelt, respektiert und preist.",
      "Das mögliche Erscheinen eines Nilbogs hat dazu geführt, dass jede Heerschar mindestens einen Goblin zum Hofnarren ernennt. Dieser Narr unterliegt keinen Beschränkungen, er darf überall hingehen, wo er will, und tun und lassen, was er möchte. Die Position ist unter Goblins heiß begehrt, denn selbst wenn der Narr offensichtlich kein Nilbog ist, dulden Hobgoblins und Grottenschrate sein chaotisches Verhalten.",
      "Der Nilbog ist ein unsichtbarer Geist, der nur von Goblins Besitz ergreift. Ohne Wirt hat der Geist eine Flugbewegungsrate von 9 m und kann weder sprechen noch angegriffen werden. Als einzige mögliche Aktion darf er versuchen, einen Goblin innerhalb von 1,5 m in Besitz zu nehmen. Das Ziel muss einen Charismarettungswurf gegen SG 15 ablegen, um dem Versuch zu widerstehen. Solange der Goblin besessen ist, wird seine Gesinnung chaotisch böse, sein Charisma steigt auf 15 und er erhält die Nilbog-Merkmale sowie die Reaktion Umkehr des Schicksals. Stirbt der Wirt oder endet die Besessenheit durch einen Zauber wie Weihen, Schutzkreis oder Schutz vor Gut und Böse, sucht der Geist sich ein anderes Ziel. Der Goblin ohne den Nilbog-Geist erhält wieder seine normalen Spielwerte."
    ],
    besonderheiten: [
      { name: "Angeborenes Zauberwirken", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Nilbog ist Charisma (Zauberrettungswurf-SG 12). Er kann angeboren die folgenden Zauber wirken, wobei keine Materialkomponenten nötig sind: Beliebig oft: Gehässiger Spott, Magierhand, Tashas Fürchterlicher Lachanfall; 1/Tag: Verwirrung." },
      { name: "Nilbogismus", beschreibung: "Jede Kreatur, die den Nilbog zu verletzen versucht, muss erst einen erfolgreichen Charismarettungswurf gegen SG 12 ablegen, um nicht bis zum Ende ihres nächsten Zugs bezaubert zu werden. Eine Kreatur, die auf diese Weise bezaubert ist, muss ihre Aktion verwenden, um den Nilbog zu verehren. Der Nilbog kann keine Trefferpunkte zurückerhalten (auch nicht durch magische Heilung), außer durch die Reaktion Umkehr des Schicksals." },
      { name: "Behändes Entkommen", beschreibung: "Der Nilbog kann die Rückzug- oder Versteckenaktion in jedem seiner Züge als Bonusaktion ausführen." }
    ],
    aktionen: [
      { name: "Narrenzepter", beschreibung: "Nahkampfwaffenangriff: +4 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 5 (1W6+2) Wuchtschaden." },
      { name: "Kurzbogen", beschreibung: "Fernkampfwaffenangriff: +4 zum Treffen, Reichweite 24/96 m, ein Ziel. Treffer: 5 (1W6+2) Stichschaden." }
    ],
    bonusaktionen: [],
    reaktionen: [
      { name: "Umkehr des Schicksals", beschreibung: "Wenn eine andere Kreatur dem Nilbog Schaden zufügt, verringert der Nilbog den Schaden auf 0 und erhält 1W6 Trefferpunkte zurück." }
    ],
    legendaere_aktionen: null,
    source: "Almanach der Monster"
