      "Wird der Stamm von einer Seuche heimgesucht, isolieren die Hände von Yurtrus die Erkrankten. Jene, die gerettet, aber nicht geheilt werden können, erfahren eine besondere Behandlung. Die Priester kultivieren die Krankheiten der sogenannten Genährten und verwandeln die Kreaturen in Instrumente des Schutzes und Waffen des Krieges. Wenn Orks in die Schlacht ziehen, ist es oft eine Gruppe von Genährten, die als Erstes vorstürmt – sich selbst opfernd, wollen sie den Feind zermürben, indem sie den abscheulichen Segen von Yurtrus unter ihnen verbreiten."
