    beschreibung: [
      "Yurtrus ist der Orkgott des Todes und der Krankheiten. Er ist ein schreckliches Ungeheuer, dessen Äußeres durch Fäulnis und Infektionen verunstaltet ist, abgesehen von seinen perfekten, glatten weißen Händen.",
      "Orkpriester, die für den Übergang vom Leben zum Tod zuständig sind, werden von den anderen Mitgliedern des Stammes als Hände von Yurtrus bezeichnet. Sie hausen in den Randbereichen des Hortes und kommunizieren mit anderen Orks für gewöhnlich nur durch die Anhänger von Luthic als Vermittler. Die Hände von Yurtrus tragen blasse Handschuhe aus der gebleichten Haut anderer Humanoider (vorzugsweise Elfen), welche die Verbindung zu ihrem Gott symbolisieren, und werden daher manchmal Weiße Hände genannt.",
      "Jeder Ork weiß, dass die Priester das Tor des Stammes zu seinen Ahnen sind. Stirbt ein Ork, der dem Stamm gut gedient hat, vollziehen sie Rituale, die ihn in Gruumshs Reich schicken sollen.",
      "Wie es für Anhänger eines stummen Gottes angemessen ist, schneiden sich die Hände von Yurtrus die Zunge heraus, um ihre Gottheit zu preisen, ähnlich wie ein Auge des Gruumsh einen seiner Augäpfel entfernt."
    ],
