    beschreibung: [
      "Ilneval ist Gruumshs Hauptmann in der Schlacht, ein verschlagener Stratege, der tapfer die Soldaten des Einäugigen kommandiert. Unter den Orks ehren Krieger, die Ilneval verehren, ihrer Gottheit nach. Sie lernen, ihre Kameraden auf Arten zu befehligen, die unvorhersehbar sind, aber dabei helfen, den Sieg zu sichern.",
      "Die weisesten unter diesen Anführern erlangen Ilnevals Gunst und werden zu Klingen, taktischen Experten, die ihren Häuptling in Fragen des Krieges beraten. Klingen führen von der Front aus und schreiten furchtlos in den Kampf, während sie ihren Untergebenen Befehle zubrüllen. Eine Klinge weiß, wie sie die Wildheit der Orks voll ausnutzen kann, und leitet die gewöhnlichen Krieger dazu an, gemeinsam gegen Feinde vorzugehen."
    ],
