      { name: "Feindzerschmetterer von Ilneval", beschreibung: "Trifft der Ork beim Angriff mit seinem Langschwert, bestimmt er den Schaden mit einem zusätzlichen Schadenswürfel (in den Angriff bereits eingerechnet)." }
