      { name: "Ilnevals Kommando (Aufladung 4–6)", beschreibung: "Bis zu drei verbündete Orks, die sich innerhalb von 36 m um diesen Ork befinden und ihn hören können, dürfen ihre Reaktion verwenden, um einen Waffenangriff auszuführen." }
