      { name: "Sporen (1/Tag)", beschreibung: "Dem Pflanzenpygmäen entsteigt eine Wolke aus toxischen Sporen mit 4,5 m Radius. Die Wolke breitet sich um Ecken aus. Jede Kreatur in dem Bereich, die keine Pflanze ist, muss einen erfolgreichen Konstitutionsrettungswurf gegen SG 12 ablegen, um nicht vergiftet zu werden. Solange eine Kreatur auf diese Weise vergiftet ist, erleidet sie 9 (2W8) Punkte Giftschaden zu Beginn eines jeden ihrer Züge. Ein Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt auf ihm bei einem Erfolg beenden." }
