    beschreibung: [
      "Fäulnismaden sind fingergroße Maden, die totes Fleisch fressen, sich aber auch von Pflanzen ernähren können. Sie befallen Leichen und Haufen verwesenden Materials und greifen jedes Wesen an, das sie bei der Nahrungsaufnahme stört. Haben sie sich in das Fleisch einer lebenden Kreatur gegraben, nagen sie sich instinktiv in Richtung des Herzens vor, um den Wirt zu töten.",
      "Fäulnismaden stellen sowohl einzeln als auch in Form eines Schwarms eine Bedrohung dar. Eine einzelne Made benötigt keine Spielwerte. Eine Kreatur, die in Kontakt mit ihr kommt, muss einen Geschicklichkeitsrettungswurf gegen SG 10 ablegen. Bei einem Misserfolg gräbt sich die Made ins Fleisch der Kreatur und verursacht 3 (1W6) Punkte Stichschaden zu Beginn eines jeden Zugs des Wirts. Wird die Wunde vor Ende des nächsten Zugs der Kreatur mit Feuer behandelt, erleidet diese 1 Punkt Feuerschaden und die Fäulnismade stirbt. Zu einem späteren Zeitpunkt hat sich die Made bereits zu tief unter die Haut gegraben, um verbrannt werden zu können. Beendet eine Kreatur, die von einer oder mehreren Fäulnismaden befallen ist, ihren Zug mit 0 Trefferpunkten, stirbt sie, da sich die Maden ins Herz fressen. Jeder Effekt, der Krankheiten heilt, tötet alle Fäulnismaden, die das Ziel befallen haben. Einen Leichnam zu verbrennen, beseitigt alle dieser Kreaturen in seinem Inneren."
    ],
