    besonderheiten: [
      { name: "Beleuchtung", beschreibung: "Als Bonusaktion kann der Schwarm in einem Radius von 1,5 m dämmriges Licht aus seinen Gehirnen ausstrahlen oder die Beleuchtung verstärken, sodass sie helles Licht in einem Radius von 1,5 bis 6 m erzeugen (und dämmriges Licht in einem zusätzlichen Bereich mit dem gleichen Radius), oder das Licht löschen." },
      { name: "Angeborenes Zauberwirken (Psionik)", beschreibung: "Das Attribut zum Wirken angeborener Zauber für den Schwarm ist Intelligenz (Zauberrettungswurf-SG 13). Solange er mehr als die Hälfte seiner Trefferpunkte besitzt, kann der Schwarm angeboren die folgenden Zauber wirken, wobei keine Komponenten nötig sind: Beliebig oft: Befehl, Gedanken wahrnehmen, Sprachen verstehen. Jeweils 1/Tag: Monster beherrschen, Verwirrung." },
      { name: "Schwarm", beschreibung: "Der Schwarm kann sich im Bereich einer anderen Kreatur aufhalten und andersherum. Er ist in der Lage, sich durch jede Öffnung zu bewegen, die groß genug für eine winzige Ratte ist. Der Schwarm kann keine Trefferpunkte zurückerhalten oder temporäre Trefferpunkte erlangen." },
      { name: "Telepathische Hülle", beschreibung: "Der Schwarm ist immun gegen jeden Effekt, der seine Emotionen spüren oder seine Gedanken lesen würde, sowie gegen Erkenntniszauber." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 0 m, ein Ziel im Bereich des Schwarms. Treffer: 14 (4W6) Stichschaden, oder 7 (2W6) Stichschaden, wenn der Schwarm die Hälfte seiner Trefferpunkte oder weniger besitzt." }
    ],
