    attribute: { STR: 15, DEX: 8, CON: 15, INT: 6, WIS: 10, CHA: 8 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: [],
