    zustandsimmunitaeten: [],
    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Versteht Aqual und Gemein, kann aber nicht sprechen"],
    umgebung: ["Gewässer", "Küste", "Ozean"],
    bild: "assets/images/monster/almanach/seegezuecht.png",
    beschreibung: [
      "Viele der Geschichten, die als Seemannslieder gesungen werden und in Hafentavernen die Runde machen, erzählen von Leuten, die ans Meer verloren gingen, aber nicht einfach ertranken und verschwanden. Diese Unglückseligen werden vom Ozean geraubt und leben fortan als das Seegezücht, das die Wogen als gequältes Abbild ihres ehemaligen Selbst heimsucht. Korallen bedecken sie, Seepocken klammern sich an ihre kalte Haut. Lungen, die einst mit Luft gefüllt waren, atmen jetzt auch Wasser.",
      "Knechte der Tiefe. Kraken, Morkoth, Seevetteln, Marids, Sturmriesen, Drachenschildkröten – all diese Meereskreaturen und mehr können Sterbliche zeichnen und sie als Schergen in ihren Dienst zwingen – etwa durch einen finsteren Pakt oder einen Fluch. Sobald die Person in eine fischartige Gestalt verwandelt wurde, vermag sie das Meer nur noch kurzfristig zu verlassen, ohne den Tod zu riskieren.",
      "Anatomische Vielfältigkeit. Seegezüchte gibt es in einer Vielzahl von Formen. Das eine besitzt vielleicht Tentakel anstelle eines Arms, das andere die Kiefer eines Hais, die Stacheln eines Seeigels, die Flossen eines Wals, Oktopusaugen, Haare aus Seetang oder jede Kombination derartiger Merkmale. Die fischartigen Körperteile verleihen einigen Seegezüchten Fähigkeiten, die über die gewöhnlicher Humanoider weit hinausgehen."
    ],
    besonderheiten: [
      { name: "Eingeschränkte Amphibie", beschreibung: "Das Seegezücht kann Luft und Wasser atmen, muss aber mindestens einmal am Tag für 1 Minute im Meer untertauchen, um nicht zu ersticken." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Das Seegezücht führt drei Angriffe aus: zwei waffenlose Angriffe und einen entsprechend seiner Fischanatomie." },
      { name: "Waffenloser Angriff", beschreibung: "Nahkampf-Waffenangriff: +4 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 4 (1W4+2) Wuchtschaden." },
      { name: "Fischanatomie", beschreibung: "Das Seegezücht verfügt über eine oder mehrere der folgenden Angriffsoptionen, wenn es die dazu notwendigen anatomischen Voraussetzungen besitzt." },
      { name: "Fischanatomie: Biss", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 4 (1W4+2) Stichschaden." },
      { name: "Fischanatomie: Giftstacheln", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 3 (1W6) Giftschaden, und dem Ziel muss ein Konstitutionsrettungswurf gegen SG 12 gelingen, um nicht für 1 Minute vergiftet zu werden. Das Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt bei einem Erfolg beenden." },
      { name: "Fischanatomie: Tentakel", beschreibung: "Nahkampf-Waffenangriff: +5 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 5 (1W6+2) Wuchtschaden, und das Ziel ist gepackt (SG 12 zum Entkommen), wenn seine Größenkategorie mittelgroß oder kleiner ist. Bis der Haltegriff endet, kann das Seegezücht diesen Tentakel nicht auf ein anderes Ziel verwenden." }
    ],
    bonusaktionen: [],
