      "Seher sind Spezialisten der arkanen Kunst, deren Grundlage die Erkenntnis ist, dass Wissen Macht bedeutet. Einige sind distanziert, verhalten sich mysteriös und sagen Omen und Ereignisse vorher. Andere sind schlicht Besserwisser, die Geheimnisse und Einsichten verraten, um den eigenen Status oder Ruf zu mehren."
