    sprachen: ["Tlincalli"],
    umgebung: ["Höhle", "Ruinen", "Wüste"],
    bild: "assets/images/monster/almanach/tlincalli.png",
    beschreibung: [
      "Tlincalli, auch Skorpionmenschen genannt, sind von Chitin-Platten bedeckte Kreaturen, humanoid von der Hüfte aufwärts und mit dem Unterleib eines gewaltigen Skorpions, samt Stachel am Ende eines langen Schwanzes.",
      "Wüstennomaden. Das Volk der Tlincalli führt ein asketisches Leben. Es reist durch trockene Ländereien und jagt bei Morgen- und Abenddämmerung. In den Stunden dazwischen warten die Skorpionmenschen, bis die Hitze des Tages oder die Kälte der Nacht vorüber ist, indem sie sich in losen Sand oder Erde eingraben oder in Ruinen oder flachen Höhlen lauern.",
      "Giftige Eier. Ihre Eier legen die Skorpionmenschen an warmen Orten ohne direkte Sonneneinstrahlung, oft zwischen Kakteen in der Nähe ihres Lagers. Die Schale der Eier ist sehr hart und überzogen mit einem lähmenden Gift, ähnlich dem, das die Tlincalli in ihren Stacheln erzeugen.",
      "Grausige Entführer. Die Skorpionmenschen essen, was sie töten, aber sie machen auch Gefangene. Nachdem sie Opfer mit ihren Stacheln gelähmt haben, fesseln sie die Gefangenen mit dornenbesetzten Ketten, bringen sie in ihr Lager und binden sie an Kakteen oder Felsen. Dort warten die armen Seelen, bis die Sonne untergeht und die neu geschlüpften Jungen hervorkommen, um sie bei lebendigem Leib zu fressen.",
      "Stolze Jäger. Die Tlincalli sehen sich selbst als Volk großer Jäger. Wenn ein Stamm mächtigeren Jägern begegnet, wie einem blauen Drachen, muss der Anführer des Stammes entscheiden, ob die Gruppe sich der überlegenen Kreatur unterwirft, weiterzieht oder bis zum Tode kämpft, um ihre eigene Vorrangstellung zu beweisen."
    ],
    besonderheiten: [],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Tlincalli führt zwei Angriffe aus: einen mit seinem Langschwert oder seiner Stachelkette und einen mit seinem Stachel." },
      { name: "Langschwert", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 7 (1W8+3) Hiebschaden, oder 8 (1W10+3) Hiebschaden, wenn die Waffe mit beiden Händen geführt wird." },
      { name: "Stachelkette", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 6 (1W6+3) Stichschaden, und das Ziel ist gepackt (SG 11 zum Entkommen), wenn seine Größenkategorie groß oder kleiner ist. Bis der Haltegriff endet, ist die Kreatur festgesetzt und der Tlincalli kann die Stachelkette nicht gegen ein anderes Ziel verwenden." },
      { name: "Stachel", beschreibung: "Nahkampf-Waffenangriff: +6 zum Treffen, Reichweite 1,5 m, eine Kreatur. Treffer: 6 (1W6+3) Stichschaden plus 14 (4W6) Giftschaden, und das Ziel muss einen erfolgreichen Konstitutionsrettungswurf gegen SG 14 ablegen, um nicht für 1 Minute vergiftet zu werden. Wenn der Rettungswurf um 5 oder mehr Punkte misslingt, ist das Ziel zusätzlich gelähmt, solange es vergiftet ist. Das Ziel kann den Rettungswurf am Ende eines jeden seiner Züge wiederholen und den Effekt bei einem Erfolg beenden." }
    ],
