    unterart: null,
    groesse: "Groß",
    gesinnung: "Neutral böse",
    cr: 10,
    xp: 5900,
    rk: 16,
    ruestungstyp: "natürliche Rüstung",
    tp: 161,
    tp_wuerfel: "17W10+68",
    bewegung: { "Fliegen": "9 m (Schweben)" },
    attribute: { STR: 18, DEX: 14, CON: 18, INT: 10, WIS: 12, CHA: 10 },
    rettungswuerfe: { KON: 8, WEI: 5 },
    fertigkeiten: { "Wahrnehmung": 5 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Blitz"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Liegend"],
    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 15,
    sprachen: ["Tiefensprache", "Gemeinsprache der Unterreiche"],
    umgebung: ["Unterirdisch", "Höhle"],
    bild: "assets/images/monster/almanach/todeskuss.png",
    beschreibung: [
      "Ein Todeskuss ist ein niederer Betrachter, der entstehen kann, wenn ein wahrer Betrachter einen intensiven Albtraum hat, der sich um den Verlust von Blut dreht. Statt Augenstielen verfügt er über zehn lange Tentakel, die jeweils in einem Maul voller Zähne enden. In Farbe und Form ähnelt er dem Betrachter, der ihn erträumt hat, aber seine Schattierung ist dumpfer.",
      "Bluttrinker. Ein Todeskuss überlebt nur, indem er Blut zu sich nimmt, durch das er elektrische Energie in seinem Körper erzeugt. Er hat paranoide Angst davor, zu verhungern, und saugt zwanghaft selbst kleine Kreaturen wie Ratten aus, um diesem Schicksal so lange wie möglich zu entgehen. Nachdem er das Blut seiner Beute getrunken hat, lässt er die Leiche für die Aasfresser zurück. Ein Todeskuss jagt bevorzugt allein. Stößt er auf einen anderen seiner Art, könnte er kämpfen, flüchten oder sich mit ihm verbrüdern, abhängig von seiner Gesundheit und seinem Stolz. Unter der Erde nutzt er seine Tentakel als Fühler, um die Umgebung in allen Richtungen zu ertasten und zu untersuchen. Über der Erde zieht er auf der Jagd seine Tentakel ein, um sie dann plötzlich auszufahren und zuzuschlagen und so seine Gegner zu überrumpeln.",
      "Einfache Taktik. Ein Todeskuss verfügt nicht über die kämpferische Finesse und Intelligenz eines Betrachters. Er könnte ein ungewöhnliches Manöver versuchen, um seine Beute unter Kontrolle zu halten (zum Beispiel indem er nach oben fliegt, wenn er es gepackt hat), aber meist befestigt er einfach einen oder mehrere seiner Tentakel an einer Kreatur und saugt ihr das Blut aus, bis sie zusammenbricht. Wenn er sich in einer überlegenen Position befindet und sein Gegner keine Gefahr darstellt, spielt er vielleicht mit seiner Beute, indem er sie langsam zerdrückt und das Leben aus ihr herauspresst.",
      "Falscher Tyrann. In schwachem Licht und mit ausgefahrenen Tentakeln kann ein Todeskuss wie ein echter Betrachter erscheinen. Er könnte sich unwissenden Kreaturen absichtlich als solcher präsentieren, aber zu dieser List greift er nur selten, da er sich für gewöhnlich auf die Jagd konzentriert und zudem weder die Selbstherrlichkeit noch die Paranoia eines wahren Betrachters besitzt. Der Todeskuss kann durch all seine Tentakelmäulern sprechen, und seine Stimme klingt nasal und schrill. Ein echter Betrachter hat wenig von dieser Kreatur zu befürchten, da er den Todeskuss mühelos töten oder ausschalten kann, ehe dieser in Nahkampfreichweite kommt. Aus Selbsterhaltung unterwirft sich ein Todeskuss deshalb meist jedem Betrachter, dem er begegnet, allerdings könnte er zu entkommen versuchen, wenn sein Meister beschäftigt ist."
    ],
    besonderheiten: [
      { name: "Blitzblut", beschreibung: "Eine Kreatur innerhalb von 1,5 m um den Todeskuss erleidet 5 (1W10) Punkte Blitzschaden, wenn sie ihn mit einem Nahkampfangriff trifft, der Stich- oder Hiebschaden verursacht." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Todeskuss führt drei Tentakel-Angriffe aus. Bis zu drei dieser Angriffe können durch Blutentzug ersetzt werden, einer pro Tentakel, die eine Kreatur gepackt hält." },
      { name: "Tentakel", beschreibung: "Nahkampf-Waffenangriff: +8 zum Treffen, Reichweite 6 m, ein Ziel. Treffer: 14 (3W6+4) Stichschaden, und das Ziel ist gepackt (SG 14 zum Entkommen), wenn seine Größenkategorie riesig oder kleiner ist. Bis der Haltegriff endet, ist die Kreatur festgesetzt und der Todeskuss kann diesen Tentakel nicht gegen ein anderes Ziel verwenden. Der Todeskuss besitzt zehn Tentakel." },
      { name: "Blutentzug", beschreibung: "Eine Kreatur, die von einem Tentakel des Todeskusses gepackt ist, muss einen Konstitutionsrettungswurf gegen SG 16 ablegen. Bei einem Misserfolg erleidet das Ziel 22 (4W10) Punkte Blitzschaden und der Todeskuss erhält halb so viele Trefferpunkte zurück." }
    ],
    bonusaktionen: [],
    reaktionen: [],
    legendaere_aktionen: null,
    source: "Almanach der Monster"
