    name: "Traumwandler der Steinriesen",
    art: "Riese",
    unterart: "Steinriese",
    groesse: "Riesig",
    gesinnung: "Chaotisch neutral",
    cr: 10,
    xp: 5900,
    rk: 18,
    ruestungstyp: "natürliche Rüstung",
    tp: 161,
    tp_wuerfel: "14W12+70",
    bewegung: { "Gehen": "12 m" },
    attribute: { STR: 23, DEX: 14, CON: 21, INT: 10, WIS: 8, CHA: 12 },
    rettungswuerfe: { GES: 6, KON: 9, WEI: 3 },
    fertigkeiten: { "Athletik": 14, "Wahrnehmung": 3 },
    schadensresistenzen: [],
    schadensimmunitaeten: [],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Verängstigt"],
    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 13,
    sprachen: ["Gemeinsprache", "Riesisch"],
    umgebung: ["Gebirge", "Hügel", "Ruinen"],
    bild: "assets/images/monster/almanach/traumwandler_der_steinriesen.png",
    beschreibung: [
      "Die Oberfläche der Welt ist ein fremdartiges Reich für die Steinriesen: wechselhaft, kurzlebig und starken Winden und plötzlichem Regen ausgesetzt. Sie ist so unbeständig wie ein Traum, und als solchen betrachten die Riesen sie auch. Nichts dort ist dauerhaft, also ist auch nichts real. Was an der Oberfläche geschieht, ist nicht von Bedeutung. Versprechen und Pakte, die dort geschlossen werden, müssen nicht eingehalten werden. Leben und sogar Kunst besitzt dort keinen Wert.",
      "Manchmal gehen Steinriesen auf Traumquesten an die Oberfläche, um eine Inspiration für ihre Kunst zu finden, Jahrzehnte währende Langeweile zu überwinden oder einfach weil sie neugierig sind. Einige, die auf diese Questen ausziehen, verlieren sich selbst in ihrem Traum. Andere werden als Strafe an die Oberfläche verbannt. Gleich aus welchem Grund, wenn sie nicht Zuflucht unter dem Stein suchen, werden diese Riesen Traumwandler.",
      "Traumwandler nehmen einen seltsamen Platz im Ordning der Steinriesen ein. Sie gelten als Ausgestoßene, werden aber trotzdem mit Respekt behandelt, da ihre Vertrautheit mit der Oberfläche sie zu wertvollen Führern macht und ihre Einsichten dazu beitragen können, dass andere Steinriesen die Gefahren begreifen, die das Leben in einem Traum birgt.",
      "Traumwandler werden von Einsamkeit, Scham und ihrer unendlich fremdartigen Umgebung in den Wahnsinn getrieben. Dieser Wahn sickert in die Welt, sodass er auch andere Kreaturen betrifft, die ihnen zu nahe kommen. Weil sie glauben, in einem Traum zu leben, in dem ihre Taten keine wirklichen Konsequenzen haben, tun Traumwandler, was sie wollen, wodurch sie zu Mächten des Chaos werden. Sie durchstreifen die Welt und sammeln Objekte und Kreaturen, die ihrem wahnsinnigen Verstand besonders wichtig erscheinen. Im Laufe der Zeit wachsen diese Dinge an ihrem Körper fest und werden von Stein umschlossen."
    ],
    besonderheiten: [
      { name: "Charme des Traumwandlers", beschreibung: "Ein Feind, der seinen Zug innerhalb von 9 m um den Riesen beginnt, muss einen Charismarettungswurf gegen SG 13 ablegen, sofern der Riese nicht kampfunfähig ist. Bei einem Misserfolg wird die Kreatur vom Traumwandler bezaubert. Die bezauberte Kreatur kann den Rettungswurf am Ende eines jeden ihrer Züge wiederholen und den Effekt bei einem Erfolg beenden. Gelingt einer Kreatur der Rettungswurf, ist sie für 24 Stunden gegen den Effekt des Merkmals dieses Riesen immun." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Riese führt zwei Angriffe mit seinem Zweihandknüppel durch." },
      { name: "Zweihandknüppel", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 4,5 m, ein Ziel. Treffer: 19 (3W8+6) Hiebschaden." },
      { name: "Versteinernde Berührung", beschreibung: "Der Riese berührt eine mittelgroße oder kleinere Kreatur innerhalb von 3 m, die von ihm bezaubert wurde. Das Ziel muss einen Konstitutionsrettungswurf gegen SG 17 ablegen. Bei einem Misserfolg erhält es den Zustand versteinert und der Riese kann es an seinem Körper befestigen. Der Zauber Vollständige Genesung und andere Magie, die Versteinerung aufzuheben vermag, hat keinen Effekt auf die versteinerte Kreatur, solange der Riese lebt. Nach seinem Tod funktioniert die Magie wieder normal und befreit die Kreatur zusätzlich dazu, dass der Zustand versteinert aufgehoben wird." },
      { name: "Felsen", beschreibung: "Fernkampf-Waffenangriff: +10 zum Treffen, Reichweite 18/72 m, ein Ziel. Treffer: 28 (4W10+6) Wuchtschaden. Wenn das Ziel eine Kreatur ist, muss es einen erfolgreichen Stärkerettungswurf gegen SG 17 ablegen, um nicht den Zustand liegend zu erhalten." }
    ],
