    sinne: ["Dunkelsicht 18 m"],
    passiveWahrnehmung: 8,
    sprachen: ["Versteht Abyssisch, Infernalisch und alle Sprachen der Person, die sie einst war (kann nicht sprechen)"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/almanach/vargouille.png",
    beschreibung: [
      "Die kreischenden und flatternden Vargouilllen sind ein grauenvoller Anblick mit ihrem Körper, der wie ein abgetrennter Kopf anmutet, und ihren fledermausartigen Schwingen anstelle von Ohren. Sie entsteigen dem Abyss, um andere Existenzebenen zu befallen. Jeder Vargouille verbreitet einen Fluch, der weitere Vertreter seiner Art erschafft.",
      "Plaggeister des Abyss. Unzählige Vargouilllen flattern durch die Höhlen und über den Himmel des Abyss. Von mächtigen und intelligenten Dämonen werden sie kaum beachtet. In den Unteren Ebenen bekommen die flatternden Wesen selten die Gelegenheit, lebendes Fleisch zu fressen – meistens lecken sie Sekrete auf, die am Boden zurückbleiben, wenn ein Unhold einen anderen erschlägt.",
      "Grausige Fortpflanzung. Der Kuss der Vargouilllen infiziert einen Humanoiden mit einem unheiligen Fluch. Nimmt dieser seinen Verlauf, führt er zu einer abscheulichen Verwandlung, während der ein abyssischer Geist in den Körper der Person eindringt. Im Laufe von Stunden wachsen dem Kopf des Opfers dämonische Merkmale wie Reifhähne, Tentakel und Hörner, und die Ohren verwandeln sich in fledermausartige Anhängsel. In den letzten Augenblicken reißt sich der Kopf in einer Blutfontäne vom Körper und wird zu einem neuen Vargouille. Sonnenlicht oder der Zauber Tageslicht können diese Verwandlung hinauszögern."
    ],
    besonderheiten: [],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampf-Waffenangriff: +4 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 5 (1W6+2) Stichschaden plus 10 (3W6) Giftschaden." },
      { name: "Kuss", beschreibung: "Der Vargouille küsst einen kampfunfähigen Humanoiden innerhalb von 1,5 m. Dem Ziel muss ein Charismarettungswurf gegen SG 12 gelingen, um nicht verflucht zu werden. Eine verfluchte Kreatur verliert 1 Punkt Charisma nach jeder Stunde und ihr Kopf nimmt ein dämonisches Aussehen an. Der Fluch wird unterbrochen, solange sich das Ziel im Sonnenlicht oder im Wirkungsbereich des Zaubers Tageslicht befindet (diese Zeit zählt nicht in Bezug auf die Effekte des Fluchs). Wenn der Charismawert des verfluchten Ziels auf 2 sinkt, stirbt es und der Kopf reißt sich vom Körper los und wird ein neuer Vargouille. Wird Fluch brechen, Vollständige Genesung oder ein ähnlicher Zauber auf das Ziel gewirkt, ehe die Verwandlung abgeschlossen ist, hebt das den Fluch auf und macht die Verwandlung rückgängig." },
      { name: "Betäubendes Kreischen", beschreibung: "Der Vargouille kreischt. Alle Humanoiden oder Tiere innerhalb von 9 m, die den Vargouille hören können, müssen einen erfolgreichen Weisheitsrettungswurf gegen SG 12 ablegen, um nicht bis zum Ende des nächsten Zugs des Unholds verängstigt zu werden. Solange ein Ziel auf diese Weise verängstigt ist, ist es auch betäubt. Wenn der Rettungswurf eines Ziels erfolgreich ist oder der Effekt endet, ist die Kreatur für 1 Stunde immun gegen das Betäubende Kreischen des Vargouilllen." }
    ],
    bonusaktionen: [],
