    attribute: { STR: 20, DEX: 12, CON: 20, INT: 13, WIS: 10, CHA: 16 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: ["Blitz", "Feuer", "Kälte"],
    schadensimmunitaeten: ["Gift"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Vergiftet"],
    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Abyssisch", "Telepathie 36 m"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/almanach/verschlinger.png",
    beschreibung: [
      "Von allen Grässlichkeiten, die Orcus entfesselt hat, gehören Verschlinger zu denen, die am meisten gefürchtet werden. Diese großen, mumienartigen Unholds streifen durch die Ebenen, verzehren Seelen und verbreiten durch ihr Beispiel Orcus' Glauben, dass alles Leben mit ewigem Tod ersetzt werden muss.",
      "Instrumente des Orcus. Ein niederer Dämon, der sich Orcus bewiesen hat, könnte das Privileg erhalten, ein Verschlinger zu werden. Der Fürst des Untodes verwandelt einen solchen Dämon in einen 2,40 m großen, ausgedörrten Humanoiden mit hohlem Brustkorb und füllt die neue Kreatur mit einem Hunger nach Seelen. Die meisten Verschlinger bleiben im Abyss oder wechseln auf die Astral- oder Ätherebene, wo sie die Pläne und Interessen des Orcus verfolgen.",
      "Quäler der Seelen. Verschlinger jagen Humanoide, um deren Körper und Seele zu verzehren. Nachdem der Unhold ein Ziel an den Rand des Todes gebracht hat, nimmt er den Körper des Opfers in sich auf und hält ihn in seinem Brustkorb gefangen. Wenn das Opfer stirbt, durchläuft es eine schreckliche Transformation und bricht als untoter Diener aus dem Körper des Monsters hervor.",
      "Unheilige Natur. Ein Verschlinger braucht weder Luft noch Nahrung (außer Seelen), Wasser oder Schlaf."
    ],
    besonderheiten: [],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Verschlinger führt zwei Klauen-Angriffe aus und kann entweder Seelengefängnis oder Seelenreißer einsetzen." },
      { name: "Klauen", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 1,5 m, ein Ziel. Treffer: 12 (2W6+5) Hiebschaden plus 21 (6W6) nekrotischer Schaden." },
      { name: "Seelengefängnis", beschreibung: "Der Verschlinger bestimmt einen lebenden Humanoiden mit 0 Trefferpunkten, den er sehen kann und der sich innerhalb von 9 m befindet. Das Ziel wird in den Brustkorb des Verschlingers teleportiert und ist dort gefangen. Eine eingesperrte Kreatur ist im Nachteil bei allen Todesrettungswürfen. Wenn sie in diesem Gefängnis stirbt, erhält der Verschlinger 25 Trefferpunkte zurück, lädt Seelenreißer auf und darf in seinem nächsten Zug eine zusätzliche Aktion ausführen. Zu Beginn seines nächsten Zugs würgt er die getötete Kreatur hervor, die sich daraufhin als Untoter erhebt: Besaß das Opfer 2 oder weniger Trefferwürfel, wird es ein Zombie; hatte es 3 bis 5 Trefferwürfel, wird es ein Ghoul; andernfalls verwandelt es sich in einen Gruftschrecken. Ein Verschlinger kann nur eine Kreatur auf einmal gefangen halten." },
      { name: "Seelenreißer (Aufladung 6)", beschreibung: "Der Verschlinger erschafft einen Wirbel lebensentziehender Energie, der ihn in einem Radius von 6 m umgibt. Jeder Humanoide in diesem Bereich muss einen Konstitutionsrettungswurf gegen SG 18 ablegen. Bei einem Misserfolg nimmt eine Kreatur 44 (8W10) Punkte nekrotischen Schaden oder die Hälfte bei einem erfolgreichen Rettungswurf. Der Schaden erhöht sich um 10 für jeden lebenden Humanoiden mit 0 Trefferpunkten im Bereich." }
    ],
    bonusaktionen: [],
