    attribute: { STR: 18, DEX: 17, CON: 16, INT: 5, WIS: 12, CHA: 7 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: ["Wucht-, Hieb- und Stichschaden durch nicht-magische Angriffe (außer versilbert)"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Erschöpfung", "Bezaubert", "Verängstigt"],
