      { name: "Klaue (nur Anathema-Gestalt)", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 3 m, ein Ziel. Treffer: 13 (2W6+6) Hiebschaden." },
      { name: "Umschlingen", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 4,5 m, eine Kreatur der Größenkategorie groß oder kleiner. Treffer: 13 (2W6+6) Wuchtschaden plus 7 (2W6) Säureschaden, und das Ziel ist gepackt (SG 16 zum Entkommen). Bis der Haltegriff endet, ist das Ziel festgesetzt und erleidet 13 (2W6+6) Wuchtschaden plus 7 (2W6) Säureschaden zu Beginn eines jeden seiner Züge. Das Anathema kann währenddessen kein weiteres Ziel umschlingen." },
      { name: "Wirbelwind der Bisse", beschreibung: "Nahkampf-Waffenangriff: +10 zum Treffen, Reichweite 3 m, eine Kreatur. Treffer: 27 (6W6+6) Stichschaden plus 14 (4W6) Giftschaden." }
