      "Auch wenn Brutwächter nur eine eingeschränkte Intelligenz besitzen, erfüllen sie einfache, aber wichtige Aufgaben in der Gesellschaft der Schlangenmenschen, wie das Bewachen der Eier oder das Patrouillieren auf der Suche nach Eindringlingen. Die Yuan-ti bezeichnen Brutwächter als 'nistachii', was 'Eihüter' bedeutet.",
