      "Ein Gedankenflüsterer ist schwer greifbar, manipulativ, unvorhersehbar und bereit, Gefährten und Rivalen gleichermaßen zu betrügen und zu töten, wenn es ihm nützt. Selbst unter Yuan-ti sind Gedankenflüsterer dafür bekannt, selbstherrlich und hinterhältig zu sein und beim ersten Anzeichen von Gefahr zu flüchten. Dieser Halbblütige ist von Typ 1 und besitzt einen menschlichen Körper und den Kopf einer Schlange."
