      { name: "Zauberwirken (nur Yuan-ti-Gestalt)", beschreibung: "Der Yuan-ti ist ein Zauberwirker der 6. Stufe. Sein Attribut zum Zauberwirken ist Charisma (Zauberrettungswurf-SG 13, +5 zum Treffen mit Zauberangriffen). Er erhält seine verbrauchten Zauberplätze zurück nach einer kurzen oder langen Rast. Zaubertricks (beliebig oft): Botschaft, Einfache Illusion, Freundschaft, Gift versprühen, Schauriger Strahl (Reichweite 90 m, +3 Bonus auf jeden Schadenswurf), Taschenspielerei. 1.–3. Grad (2 Zauberplätze des 3. Grades): Fliegen, Gedanken wahrnehmen, Hypnotisches Muster, Illusionsschrift, Krone des Wahnsinns, Person bezaubern, Rascher Rückzug." },
      { name: "Sseths Segen", beschreibung: "Wenn der Yuan-ti einen Gegner auf 0 Trefferpunkte reduziert, erhält er 9 temporäre Trefferpunkte." }
